import React, { useState, useEffect } from 'react';
import { DollarSign, Tag, Calendar, FileText, CreditCard, Building2, X } from 'lucide-react';
import { getCategories, createExpense, updateExpense } from '../../../services/budgetApi';
import { markDashboardDataExists } from '../../../utils/dashboardDataState';

const ExpenseForm = ({ initialValues, onSuccess, onCancel }) => {
    const [categories, setCategories] = useState([]);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [formData, setFormData] = useState({
        category: '',
        amount: '',
        description: '',
        expense_date: new Date().toISOString().split('T')[0],
        payment_method: 'CASH',
        merchant: '',
        notes: '',
        currency: 'KES',
    });

    const isEditing = !!initialValues;

    useEffect(() => {
        loadCategories();
    }, []);

    useEffect(() => {
        if (initialValues) {
            setFormData({
                category: initialValues.category ? String(initialValues.category) : '',
                amount: initialValues.amount || '',
                description: initialValues.description || '',
                expense_date: initialValues.expense_date || new Date().toISOString().split('T')[0],
                payment_method: initialValues.payment_method || 'CASH',
                merchant: initialValues.merchant || '',
                notes: initialValues.notes || '',
                currency: initialValues.currency || 'KES',
            });
        }
    }, [initialValues]);

    const loadCategories = async () => {
        try {
            const data = await getCategories();
            setCategories(data);
        } catch (error) {
            console.error('Failed to load categories:', error);
        }
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData((prev) => ({ ...prev, [name]: value }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            let submitData;

            if (isEditing) {
                // When editing, EXCLUDE the category field entirely
                const { category, ...dataWithoutCategory } = formData;
                submitData = dataWithoutCategory;
                
                console.log('Updating expense (without category):', submitData);
                await updateExpense(initialValues.uuid, submitData);
            } else {
                // When creating, include category
                submitData = {
                    ...formData,
                    category: formData.category ? Number(formData.category) : '',
                };

                console.log('Creating expense:', submitData);
                await createExpense(submitData);
                
                // Reset form only for new expenses
                setFormData({
                    category: '',
                    amount: '',
                    description: '',
                    expense_date: new Date().toISOString().split('T')[0],
                    payment_method: 'CASH',
                    merchant: '',
                    notes: '',
                    currency: 'KES',
                });
            }

            if (onSuccess) onSuccess();
            markDashboardDataExists();
        } catch (error) {
            console.error('Failed to save expense:', error);
            setIsSubmitting(false);
        }
    };

    return (
        <div className="rounded-[1.75rem] border border-slate-200 bg-white p-6 shadow-sm">
            {isEditing && onCancel && (
                <button
                    onClick={onCancel}
                    className="absolute right-4 top-4 rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
                >
                    <X size={20} />
                </button>
            )}

            <div className="mb-6">
                <h3 className="text-lg font-bold text-slate-900">
                    {isEditing ? 'Edit Expense' : 'Record Expense'}
                </h3>
                <p className="mt-1 text-sm text-slate-600">
                    {isEditing ? 'Update expense details' : 'Track your spending in real-time'}
                </p>
            </div>

            <form onSubmit={handleSubmit} className="space-y-5">
                {/* Category */}
                <div>
                    <label className="mb-2 flex items-center gap-2 text-sm font-semibold text-slate-700">
                        <Tag size={16} className="text-slate-500" />
                        Category
                    </label>
                    {isEditing ? (
                        // Show category as read-only text when editing
                        <div className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-medium text-slate-700">
                            {initialValues.category_name}
                        </div>
                    ) : (
                        // Show dropdown when creating
                        <select
                            name="category"
                            value={formData.category}
                            onChange={handleChange}
                            required
                            className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-900 shadow-sm transition-all focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20"
                        >
                            <option value="">Select category</option>
                            {categories.map(cat => (
                                <option key={cat.uuid || cat.id} value={cat.value}>
                                    {cat.name}
                                </option>
                            ))}
                        </select>
                    )}
                    {isEditing && (
                        <p className="mt-1 text-xs text-slate-500">
                            Category cannot be changed after creation
                        </p>
                    )}
                </div>

                {/* Amount */}
                <div>
                    <label className="mb-2 flex items-center gap-2 text-sm font-semibold text-slate-700">
                        <DollarSign size={16} className="text-slate-500" />
                        Amount
                    </label>
                    <div className="relative">
                        <input
                            type="number"
                            name="amount"
                            value={formData.amount}
                            onChange={handleChange}
                            required
                            min="0"
                            step="0.01"
                            placeholder="0.00"
                            className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 pl-10 text-sm font-medium text-slate-900 shadow-sm transition-all focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20"
                        />
                        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-sm font-bold text-slate-400">
                            KES
                        </span>
                    </div>
                </div>

                {/* Description */}
                <div>
                    <label className="mb-2 flex items-center gap-2 text-sm font-semibold text-slate-700">
                        <FileText size={16} className="text-slate-500" />
                        Description
                    </label>
                    <input
                        type="text"
                        name="description"
                        value={formData.description}
                        onChange={handleChange}
                        required
                        placeholder="What did you spend on?"
                        className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-900 shadow-sm transition-all focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20"
                    />
                </div>

                {/* Date & Payment Method */}
                <div className="grid gap-4 sm:grid-cols-2">
                    <div>
                        <label className="mb-2 flex items-center gap-2 text-sm font-semibold text-slate-700">
                            <Calendar size={16} className="text-slate-500" />
                            Date
                        </label>
                        <input
                            type="date"
                            name="expense_date"
                            value={formData.expense_date}
                            onChange={handleChange}
                            required
                            className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-900 shadow-sm transition-all focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20"
                        />
                    </div>

                    <div>
                        <label className="mb-2 flex items-center gap-2 text-sm font-semibold text-slate-700">
                            <CreditCard size={16} className="text-slate-500" />
                            Payment Method
                        </label>
                        <select
                            name="payment_method"
                            value={formData.payment_method}
                            onChange={handleChange}
                            className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-900 shadow-sm transition-all focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20"
                        >
                            <option value="CASH">Cash</option>
                            <option value="CARD">Card</option>
                            <option value="MOBILE_MONEY">Mobile Money</option>
                            <option value="BANK_TRANSFER">Bank Transfer</option>
                            <option value="OTHER">Other</option>
                        </select>
                    </div>
                </div>

                {/* Merchant (Optional) */}
                <div>
                    <label className="mb-2 flex items-center gap-2 text-sm font-semibold text-slate-700">
                        <Building2 size={16} className="text-slate-500" />
                        Merchant (Optional)
                    </label>
                    <input
                        type="text"
                        name="merchant"
                        value={formData.merchant}
                        onChange={handleChange}
                        placeholder="Store or service name"
                        className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-medium text-slate-900 shadow-sm transition-all focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20"
                    />
                </div>

                {/* Notes (Optional) */}
                <div>
                    <label className="mb-2 block text-sm font-semibold text-slate-700">
                        Notes (Optional)
                    </label>
                    <textarea
                        name="notes"
                        value={formData.notes}
                        onChange={handleChange}
                        rows="2"
                        placeholder="Additional details..."
                        className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-900 shadow-sm transition-all focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20"
                    />
                </div>

                {/* Submit Button */}
                <div className="flex gap-3">
                    {isEditing && onCancel && (
                        <button
                            type="button"
                            onClick={onCancel}
                            disabled={isSubmitting}
                            className="flex-1 rounded-xl border border-slate-200 bg-white px-6 py-3 text-sm font-bold text-slate-700 transition-all hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-60"
                        >
                            Cancel
                        </button>
                    )}
                    <button
                        type="submit"
                        disabled={isSubmitting}
                        className="flex-1 rounded-xl bg-primary-600 px-6 py-3 text-sm font-bold text-white shadow-lg shadow-primary-600/30 transition-all hover:bg-primary-700 hover:shadow-xl disabled:cursor-not-allowed disabled:opacity-60"
                    >
                        {isSubmitting ? (isEditing ? 'Updating...' : 'Recording...') : (isEditing ? 'Update Expense' : 'Record Expense')}
                    </button>
                </div>
            </form>
        </div>
    );
};

export default ExpenseForm;

import React, { useState } from 'react';
import { Trash2, Edit2, MoreVertical, ShoppingBag } from 'lucide-react';
import { formatCurrency, formatDateShort } from '../../../utils/budgetHelpers';
import { deleteExpense } from '../../../services/budgetApi';
import ExpenseForm from './ExpenseForm';

const ExpenseList = ({ expenses, onUpdate, compact = false }) => {
    const [activeMenu, setActiveMenu] = useState(null);
    const [deletingId, setDeletingId] = useState(null);
    const [editingExpense, setEditingExpense] = useState(null);

    const handleDelete = async (uuid) => {
        if (!window.confirm('Delete this expense?')) return;

        setDeletingId(uuid);
        try {
            await deleteExpense(uuid);
            if (onUpdate) onUpdate();
        } catch (error) {
            console.error('Failed to delete expense:', error);
        } finally {
            setDeletingId(null);
        }
    };

    const getPaymentMethodBadge = (method) => {
        const badges = {
            CASH: { label: 'Cash', color: 'emerald' },
            CARD: { label: 'Card', color: 'indigo' },
            MOBILE_MONEY: { label: 'M-Pesa', color: 'green' },
            BANK_TRANSFER: { label: 'Bank', color: 'blue' },
            OTHER: { label: 'Other', color: 'slate' },
        };
        return badges[method] || badges.OTHER;
    };

    if (!expenses || expenses.length === 0) {
        return (
            <div className="flex min-h-[260px] items-center justify-center rounded-[1.75rem] border border-slate-200 bg-white p-8 shadow-sm">
                <div className="text-center">
                    <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-slate-100">
                        <ShoppingBag className="h-8 w-8 text-slate-400" />
                    </div>
                    <h3 className="text-lg font-bold text-slate-900">No Expenses Yet</h3>
                    <p className="mt-2 text-sm text-slate-600">
                        Start recording your expenses to track spending
                    </p>
                </div>
            </div>
        );
    }

    return (
        <>
            <div className="space-y-4">
                <div className="rounded-[1.75rem] border border-slate-200 bg-white shadow-sm">
                    <div className="border-b border-slate-100 px-6 py-4">
                        <h3 className="text-lg font-bold text-slate-900">Recent Expenses</h3>
                        <p className="mt-1 text-sm text-slate-600">{expenses.length} expense{expenses.length !== 1 ? 's' : ''} recorded</p>
                    </div>

                    <div className="divide-y divide-slate-100">
                        {expenses.map((expense) => {
                            const isDeleting = deletingId === expense.uuid;
                            const paymentBadge = getPaymentMethodBadge(expense.payment_method);

                            return (
                                <div
                                    key={expense.uuid}
                                    className={`group px-6 py-4 transition-all hover:bg-slate-50 ${
                                        isDeleting ? 'opacity-50' : ''
                                    }`}
                                >
                                    <div className="flex items-start justify-between gap-4">
                                        {/* Left: Details (NO ICON) */}
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-start justify-between gap-2">
                                                <div className="flex-1 min-w-0">
                                                    <h4 className="font-semibold text-slate-900 truncate">
                                                        {expense.description}
                                                    </h4>
                                                    <p className="mt-0.5 text-xs text-slate-500">
                                                        {expense.category_name}
                                                        {expense.merchant && ` • ${expense.merchant}`}
                                                    </p>
                                                </div>
                                                
                                                <div className="text-right shrink-0">
                                                    <p className="text-lg font-bold text-slate-900">
                                                        {formatCurrency(expense.amount, expense.currency)}
                                                    </p>
                                                </div>
                                            </div>

                                            <div className="mt-2 flex items-center gap-2">
                                                <span className="text-xs text-slate-500">
                                                    {formatDateShort(expense.expense_date)}
                                                </span>
                                                <span className="text-slate-300">•</span>
                                                <span className={`rounded-lg bg-${paymentBadge.color}-50 px-2 py-0.5 text-xs font-semibold text-${paymentBadge.color}-700`}>
                                                    {paymentBadge.label}
                                                </span>
                                            </div>
                                        </div>

                                        {/* Right: Actions */}
                                        <div className="relative shrink-0">
                                            <button
                                                onClick={() => setActiveMenu(activeMenu === expense.uuid ? null : expense.uuid)}
                                                disabled={isDeleting}
                                                className="rounded-lg p-1.5 text-slate-400 opacity-0 transition-all group-hover:opacity-100 hover:bg-slate-100 hover:text-slate-600"
                                            >
                                                <MoreVertical size={18} />
                                            </button>

                                            {activeMenu === expense.uuid && (
                                                <>
                                                    <div
                                                        className="fixed inset-0 z-10"
                                                        onClick={() => setActiveMenu(null)}
                                                    />
                                                    <div className="absolute right-0 top-full z-20 mt-2 w-44 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-xl">
                                                        <button
                                                            onClick={() => {
                                                                setEditingExpense(expense);
                                                                setActiveMenu(null);
                                                            }}
                                                            className="flex w-full items-center gap-3 px-4 py-3 text-sm font-medium text-slate-700 transition-colors hover:bg-slate-50"
                                                        >
                                                            <Edit2 size={16} />
                                                            Edit
                                                        </button>
                                                        <button
                                                            onClick={() => {
                                                                handleDelete(expense.uuid);
                                                                setActiveMenu(null);
                                                            }}
                                                            className="flex w-full items-center gap-3 px-4 py-3 text-sm font-medium text-rose-600 transition-colors hover:bg-rose-50"
                                                        >
                                                            <Trash2 size={16} />
                                                            Delete
                                                        </button>
                                                    </div>
                                                </>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* Edit Expense Modal */}
            {editingExpense && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
                    <div className="relative w-full max-w-2xl">
                        <ExpenseForm
                            initialValues={editingExpense}
                            onSuccess={() => {
                                setEditingExpense(null);
                                if (onUpdate) onUpdate();
                            }}
                            onCancel={() => setEditingExpense(null)}
                        />
                    </div>
                </div>
            )}
        </>
    );
};

export default ExpenseList;

import React, { useState } from 'react';
import { Target, Plus, TrendingUp, Calendar, DollarSign, Star } from 'lucide-react';
import { formatCurrency, formatDate, getGoalTypeDisplay } from '../../../utils/budgetHelpers';
import { addGoalContribution } from '../../../services/budgetApi';

// Dynamic import to catch errors
const GoalForm = React.lazy(() => 
    import('./GoalForm').catch(err => {
        console.error('Failed to load GoalForm:', err);
        return { default: () => <div>GoalForm failed to load</div> };
    })
);

const GoalList = ({ goals, onUpdate, compact = false }) => {
    const [contributingTo, setContributingTo] = useState(null);
    const [contributionAmount, setContributionAmount] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [showGoalForm, setShowGoalForm] = useState(false);

    console.log('GoalList render - showGoalForm:', showGoalForm); // Debug

    const handleContribute = async (goalUuid) => {
        if (!contributionAmount || parseFloat(contributionAmount) <= 0) return;

        setIsSubmitting(true);
        try {
            await addGoalContribution(goalUuid, {
                amount: parseFloat(contributionAmount),
                notes: '',
            });
            setContributingTo(null);
            setContributionAmount('');
            if (onUpdate) onUpdate();
        } catch (error) {
            console.error('Failed to add contribution:', error);
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleOpenForm = () => {
        console.log('Opening goal form...'); // Debug
        setShowGoalForm(true);
        console.log('showGoalForm set to true'); // Debug
    };

    if (!goals || goals.length === 0) {
        return (
            <div className="flex min-h-[260px] items-center justify-center rounded-[1.75rem] border border-slate-200 bg-white p-8 shadow-sm">
                <div className="text-center">
                    <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-slate-100">
                        <Target className="h-8 w-8 text-slate-400" />
                    </div>
                    <h3 className="text-lg font-bold text-slate-900">No Goals Yet</h3>
                    <p className="mt-2 text-sm text-slate-600">
                        Set financial goals and track your progress
                    </p>
                    <button
                        onClick={handleOpenForm}
                        className="mt-4 inline-flex items-center gap-2 rounded-xl bg-primary-600 px-6 py-3 text-sm font-bold text-white shadow-lg hover:bg-primary-700"
                    >
                        <Plus size={18} />
                        Create Your First Goal
                    </button>

                    {/* Debug: Show form state */}
                    <p className="mt-4 text-xs text-slate-500">Form state: {showGoalForm ? 'OPEN' : 'CLOSED'}</p>
                </div>

                {/* Render form conditionally */}
                {showGoalForm && (
                    <React.Suspense fallback={<div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60">Loading...</div>}>
                        <GoalForm
                            onClose={() => {
                                console.log('Closing goal form...');
                                setShowGoalForm(false);
                            }}
                            onSuccess={() => {
                                console.log('Goal created successfully');
                                setShowGoalForm(false);
                                if (onUpdate) onUpdate();
                            }}
                        />
                    </React.Suspense>
                )}
            </div>
        );
    }

    return (
        <>
            {/* Header with Create Button */}
            <div className="mb-6 flex items-center justify-between">
                <div>
                    <h3 className="text-lg font-bold text-slate-900">Financial Goals</h3>
                    <p className="mt-1 text-sm text-slate-600">{goals.length} active goal{goals.length !== 1 ? 's' : ''}</p>
                </div>
                <button
                    onClick={handleOpenForm}
                    className="inline-flex items-center gap-2 rounded-xl bg-primary-600 px-5 py-2.5 text-sm font-bold text-white shadow-lg hover:bg-primary-700"
                >
                    <Plus size={18} />
                    New Goal
                </button>
            </div>

            {/* Goals Grid */}
            <div className="grid gap-6 lg:grid-cols-2 xl:grid-cols-3">
                {goals.map((goal) => {
                    const progressPercentage = goal.progress_percentage || 0;
                    const isCompleted = goal.status === 'COMPLETED';

                    return (
                        <div
                            key={goal.uuid}
                            className={`group relative overflow-hidden rounded-[1.75rem] border ${
                                isCompleted ? 'border-indigo-200 bg-gradient-to-br from-indigo-50 to-white' : 'border-slate-200 bg-white'
                            } p-6 shadow-sm transition-all hover:shadow-lg`}
                        >
                            {/* Priority Badge */}
                            {goal.is_priority && (
                                <div className="absolute right-4 top-4 rounded-full bg-amber-100 px-3 py-1 shadow-sm">
                                    <div className="flex items-center gap-1.5">
                                        <Star size={12} className="fill-amber-500 text-amber-500" />
                                        <span className="text-xs font-bold text-amber-700">Priority</span>
                                    </div>
                                </div>
                            )}

                            {/* Goal content - keeping your existing code */}
                            <div className="mb-4 flex items-start gap-3">
                                <div
                                    className="flex h-14 w-14 shrink-0 items-center justify-center rounded-xl text-2xl shadow-sm"
                                    style={{ backgroundColor: goal.color + '20' }}
                                >
                                    {goal.icon}
                                </div>
                                <div className="flex-1 min-w-0">
                                    <h4 className="text-lg font-bold text-slate-900 truncate">{goal.name}</h4>
                                    <p className="mt-0.5 text-xs font-medium text-slate-500">
                                        {getGoalTypeDisplay(goal.goal_type)}
                                    </p>
                                </div>
                            </div>

                            {/* Rest of goal card content... */}
                        </div>
                    );
                })}
            </div>

            {/* Goal Form Modal */}
            {showGoalForm && (
                <React.Suspense fallback={<div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60">Loading...</div>}>
                    <GoalForm
                        onClose={() => {
                            console.log('Closing goal form...');
                            setShowGoalForm(false);
                        }}
                        onSuccess={() => {
                            console.log('Goal created successfully');
                            setShowGoalForm(false);
                            if (onUpdate) onUpdate();
                        }}
                    />
                </React.Suspense>
            )}
        </>
    );
};

export default GoalList;

