import React, { useEffect, useState } from 'react';
import { ChevronDown, ChevronUp } from 'lucide-react';
import Button from '../../Button';

const emptyForm = {
    name: '',
    creditor: '',
    balance: '',
    interestRate: '',
    minimumPayment: '',
    dueDate: '',
    status: 'ACTIVE',
    notes: '',
    debtType: 'PERSONAL_LOAN',
    paymentFrequency: 'MONTHLY',
    startDate: '',
    isPriority: false,
    accountNumber: '',
    currency: 'KES',
};

const DebtForm = ({ initialValues, onSubmit, onCancel, isSubmitting, variant = 'card' }) => {
    const [formValues, setFormValues] = useState(emptyForm);
    const [showAdvanced, setShowAdvanced] = useState(false);
    const isModal = variant === 'modal';
    const inputClasses = isModal
        ? 'rounded-xl border border-gray-200 px-3 py-2.5 text-sm text-gray-900 outline-none transition-colors focus:border-primary-500'
        : 'rounded-2xl border border-gray-200 px-4 py-3 text-base text-gray-900 outline-none transition-colors focus:border-primary-500';
    const textareaClasses = isModal
        ? 'rounded-xl border border-gray-200 px-3 py-2.5 text-sm text-gray-900 outline-none transition-colors focus:border-primary-500'
        : 'rounded-2xl border border-gray-200 px-4 py-3 text-base text-gray-900 outline-none transition-colors focus:border-primary-500';

    useEffect(() => {
        if (initialValues) {
            setFormValues({
                name: initialValues.name ?? '',
                creditor: initialValues.creditor ?? '',
                balance: initialValues.balance ?? '',
                interestRate: initialValues.interestRate ?? '',
                minimumPayment: initialValues.minimumPayment ?? '',
                dueDate: initialValues.dueDate ?? '',
                status: initialValues.status ?? 'ACTIVE',
                notes: initialValues.notes ?? '',
                debtType: initialValues.debtType ?? 'PERSONAL_LOAN',
                paymentFrequency: initialValues.paymentFrequency ?? 'MONTHLY',
                startDate: initialValues.startDate ?? '',
                isPriority: initialValues.isPriority ?? false,
                accountNumber: initialValues.accountNumber ?? '',
                currency: initialValues.currency ?? 'KES',
            });
            setShowAdvanced(true);
            return;
        }

        setFormValues(emptyForm);
        setShowAdvanced(false);
    }, [initialValues]);

    const handleChange = (event) => {
        const { name, value, type, checked } = event.target;
        setFormValues((current) => ({
            ...current,
            [name]: type === 'checkbox' ? checked : value,
        }));
    };

    const handleSubmit = (event) => {
        event.preventDefault();
        onSubmit(formValues);
    };

    return (
        <form onSubmit={handleSubmit} className={isModal ? 'space-y-4' : 'rounded-3xl border border-gray-100 bg-white p-6 shadow-sm'}>
            {!isModal && (
                <div className="mb-6 flex items-start justify-between gap-4">
                    <div>
                        <p className="text-sm font-semibold uppercase tracking-[0.25em] text-primary-700">Debt details</p>
                        <h2 className="mt-2 text-2xl font-extrabold text-gray-900">
                            {initialValues ? 'Update debt account' : 'Add a new debt account'}
                        </h2>
                        <p className="mt-2 text-sm text-gray-600">
                            Enter the details of your debt to track it in your dashboard.
                        </p>
                    </div>
                    {initialValues && (
                        <button
                            type="button"
                            onClick={onCancel}
                            className="text-sm font-semibold text-gray-500 transition-colors hover:text-gray-700"
                        >
                            Cancel edit
                        </button>
                    )}
                </div>
            )}

            {isModal && (
                <div>
                    <p className="text-sm font-semibold uppercase tracking-[0.24em] text-primary-700">Debt details</p>
                    <p className="mt-1 text-xs leading-5 text-gray-600">
                        Add the essentials first.
                    </p>
                </div>
            )}

            <div className={`grid ${isModal ? 'gap-2.5 md:grid-cols-2' : 'gap-4 md:grid-cols-2'}`}>
                <Field label="Debt name" name="name" value={formValues.name} onChange={handleChange} placeholder="Student loan" required className={inputClasses} />
                
                <label className="flex flex-col gap-2 text-sm font-medium text-gray-700">
                    Debt type
                    <select
                        name="debtType"
                        value={formValues.debtType}
                        onChange={handleChange}
                        className={inputClasses}
                    >
                        <option value="PERSONAL_LOAN">Personal Loan</option>
                        <option value="CREDIT_CARD">Credit Card</option>
                        <option value="MOBILE_LOAN">Mobile Loan</option>
                        <option value="SACCO_LOAN">SACCO Loan</option>
                        <option value="BANK_LOAN">Bank Loan</option>
                        <option value="MORTGAGE">Mortgage</option>
                        <option value="CAR_LOAN">Car Loan</option>
                        <option value="STUDENT_LOAN">Student Loan</option>
                        <option value="BUSINESS_LOAN">Business Loan</option>
                        <option value="FAMILY_FRIEND">Family or Friend</option>
                        <option value="HIRE_PURCHASE">Hire Purchase</option>
                        <option value="OTHER">Other</option>
                    </select>
                </label>

                <Field label="Current balance" name="balance" type="number" min="0" step="0.01" value={formValues.balance} onChange={handleChange} placeholder="35000" required className={inputClasses} />
                <Field label="Interest rate (%)" name="interestRate" type="number" min="0" step="0.01" value={formValues.interestRate} onChange={handleChange} placeholder="13.5" className={inputClasses} />
                <Field label="Minimum payment" name="minimumPayment" type="number" min="0" step="0.01" value={formValues.minimumPayment} onChange={handleChange} placeholder="5000" className={inputClasses} />
                <Field label="Due date" name="dueDate" type="date" value={formValues.dueDate} onChange={handleChange} className={inputClasses} />

                <div className="flex items-center gap-3 py-2">
                    <input
                        type="checkbox"
                        id="isPriority"
                        name="isPriority"
                        checked={formValues.isPriority}
                        onChange={handleChange}
                        className="h-5 w-5 rounded border-gray-300 text-primary-600 focus:ring-primary-500"
                    />
                    <label htmlFor="isPriority" className="text-sm font-medium text-gray-700">
                        Mark as priority debt
                    </label>
                </div>

                <label className="flex flex-col gap-2 text-sm font-medium text-gray-700 md:col-span-2">
                    Description
                    <textarea
                        name="notes"
                        value={formValues.notes}
                        onChange={handleChange}
                        rows={isModal ? 2 : 3}
                        placeholder="Anything helpful like account number or repayment notes."
                        className={textareaClasses}
                    />
                </label>
            </div>

            {isModal && (
                <div className="rounded-2xl border border-slate-200 bg-slate-50/70 px-4 py-3">
                    <button
                        type="button"
                        onClick={() => setShowAdvanced((current) => !current)}
                        className="inline-flex items-center gap-2 text-sm font-semibold text-slate-700"
                    >
                        {showAdvanced ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                        {showAdvanced ? 'Hide extra details' : 'Add more details'}
                    </button>

                    {showAdvanced && (
                        <div className="mt-4 grid gap-3 md:grid-cols-2">
                            <Field label="Creditor" name="creditor" value={formValues.creditor} onChange={handleChange} placeholder="Bank or lender" className={inputClasses} />
                            <Field label="Account number" name="accountNumber" value={formValues.accountNumber} onChange={handleChange} placeholder="Optional" className={inputClasses} />

                            <label className="flex flex-col gap-2 text-sm font-medium text-gray-700">
                                Payment frequency
                                <select
                                    name="paymentFrequency"
                                    value={formValues.paymentFrequency}
                                    onChange={handleChange}
                                    className={inputClasses}
                                >
                                    <option value="WEEKLY">Weekly</option>
                                    <option value="BIWEEKLY">Every 2 weeks</option>
                                    <option value="MONTHLY">Monthly</option>
                                    <option value="QUARTERLY">Quarterly</option>
                                </select>
                            </label>

                            <Field label="Start date" name="startDate" type="date" value={formValues.startDate} onChange={handleChange} className={inputClasses} />

                            <label className="flex flex-col gap-2 text-sm font-medium text-gray-700 md:col-span-2">
                                Status
                                <select
                                    name="status"
                                    value={formValues.status}
                                    onChange={handleChange}
                                    className={inputClasses}
                                >
                                    <option value="ACTIVE">Active</option>
                                    <option value="PAID_OFF">Paid off</option>
                                    <option value="PAUSED">Paused</option>
                                    <option value="DEFAULTED">Defaulted</option>
                                </select>
                            </label>
                        </div>
                    )}
                </div>
            )}

            <div className={`mt-5 flex flex-col gap-2.5 sm:flex-row sm:justify-end ${isModal ? 'pt-0' : ''}`}>
                {isModal && (
                    <Button type="button" variant="outline" size="sm" className="justify-center" onClick={onCancel}>
                        Cancel
                    </Button>
                )}
                <Button type="submit" variant="primary" size="sm" className="justify-center" disabled={isSubmitting}>
                    {isSubmitting ? 'Saving debt...' : initialValues ? 'Save changes' : 'Add debt'}
                </Button>
                {!isModal && initialValues && (
                    <Button type="button" variant="outline" className="justify-center" onClick={onCancel}>
                        Cancel
                    </Button>
                )}
            </div>
        </form>
    );
};

const Field = ({ label, className = '', ...props }) => (
    <label className="flex flex-col gap-2 text-sm font-medium text-gray-700">
        {label}
        <input
            {...props}
            className={className || 'rounded-2xl border border-gray-200 px-4 py-3 text-base text-gray-900 outline-none transition-colors focus:border-primary-500'}
        />
    </label>
);

export default DebtForm;

import React, { useEffect, useMemo, useState } from 'react';
import { AlertCircle, Loader2, ShieldCheck } from 'lucide-react';
import DebtEntryModal from './DebtEntryModal';
import DebtList from './DebtList';
import DebtSummaryCards from './DebtSummaryCards';
import { calculateDebtSummary, createDebt, deleteDebt, getDebts, updateDebt } from '../../../services/debtApi';
import {
    createLiability as createNetworthLiability,
    deleteLiability as deleteNetworthLiability,
    getLiabilities as getNetworthLiabilities,
    getLiabilityCategories,
    updateLiability as updateNetworthLiability
} from '../../../services/networthApi';
import { markDashboardDataExists } from '../../../utils/dashboardDataState';
import { useHealthRefresh } from '../../../hooks/useHealthRefresh';

const DebtManagerPanel = ({ requestAddDebtSignal = 0 }) => {
    const { triggerHealthRefresh } = useHealthRefresh();
    const [debts, setDebts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [submitError, setSubmitError] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [deletingId, setDeletingId] = useState(null);
    const [editingDebt, setEditingDebt] = useState(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [activeTab, setActiveTab] = useState('debts');
    const [liabilities, setLiabilities] = useState([]);
    const [liabilityCategories, setLiabilityCategories] = useState([]);
    const [editingLiability, setEditingLiability] = useState(null);
    const [isLiabilityModalOpen, setIsLiabilityModalOpen] = useState(false);

    const summary = useMemo(() => calculateDebtSummary(debts), [debts]);

    const loadDebts = async () => {
        try {
            setLoading(true);
            setError('');
            const results = await getDebts();
            setDebts(results);
        } catch (err) {
            setError(err.message || 'We could not load your debt plan right now.');
        } finally {
            setLoading(false);
        }
    };

    const loadLiabilities = async () => {
        try {
            const [liabilityData, categoryData] = await Promise.all([
                getNetworthLiabilities(),
                getLiabilityCategories(),
            ]);
            setLiabilities(liabilityData.liabilities || []);
            setLiabilityCategories(categoryData || []);
        } catch (err) {
            setError(err.message || 'We could not load your liabilities right now.');
        }
    };

    useEffect(() => {
        Promise.all([loadDebts(), loadLiabilities()]);
    }, []);

    useEffect(() => {
        if (!requestAddDebtSignal) {
            return;
        }

        setEditingDebt(null);
        setSubmitError('');
        setIsModalOpen(true);
    }, [requestAddDebtSignal]);

    const handleSubmit = async (formValues) => {
        try {
            setIsSubmitting(true);
            setSubmitError('');
            if (editingDebt) {
                const savedDebt = await updateDebt(editingDebt.id, formValues);
                setDebts((current) => current.map((debt) => (debt.id === savedDebt.id ? savedDebt : debt)));
                setEditingDebt(null);
                setIsModalOpen(false);
                triggerHealthRefresh('debt:update');
            } else {
                const createdDebt = await createDebt(formValues);
                setDebts((current) => [createdDebt, ...current]);
                setIsModalOpen(false);
                markDashboardDataExists();
                triggerHealthRefresh('debt:create');
            }
        } catch (err) {
            setSubmitError(err.message || 'We could not save this debt right now.');
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleDelete = async (debtId) => {
        try {
            setDeletingId(debtId);
            setSubmitError('');
            await deleteDebt(debtId);
            setDebts((current) => current.filter((debt) => debt.id !== debtId));
            triggerHealthRefresh('debt:delete');
        } catch (err) {
            setSubmitError(err.message || 'We could not remove this debt right now.');
        } finally {
            setDeletingId(null);
        }
    };

    const handleSubmitLiability = async (formValues) => {
        try {
            setIsSubmitting(true);
            setSubmitError('');
            if (editingLiability) {
                await updateNetworthLiability(editingLiability.uuid, formValues);
                triggerHealthRefresh('liability:update');
            } else {
                await createNetworthLiability(formValues);
                markDashboardDataExists();
                triggerHealthRefresh('liability:create');
            }
            await loadLiabilities();
            setEditingLiability(null);
            setIsLiabilityModalOpen(false);
        } catch (err) {
            setSubmitError(err.message || 'We could not save this liability right now.');
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleDeleteLiability = async (liabilityId) => {
        try {
            setDeletingId(liabilityId);
            setSubmitError('');
            await deleteNetworthLiability(liabilityId);
            setLiabilities((current) => current.filter((item) => item.uuid !== liabilityId));
            triggerHealthRefresh('liability:delete');
        } catch (err) {
            setSubmitError(err.message || 'We could not remove this liability right now.');
        } finally {
            setDeletingId(null);
        }
    };

    if (loading) {
        return (
            <div className="flex min-h-[260px] items-center justify-center rounded-[1.75rem] border border-slate-200 bg-white shadow-sm">
                <div className="text-center">
                    <Loader2 className="mx-auto h-12 w-12 animate-spin text-primary-600" />
                    <p className="mt-4 text-sm font-medium text-slate-600">Loading your debt overview...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <DebtEntryModal
                isOpen={isModalOpen}
                initialValues={editingDebt}
                onSubmit={handleSubmit}
                onClose={() => {
                    if (isSubmitting) {
                        return;
                    }
                    setIsModalOpen(false);
                    setEditingDebt(null);
                    setSubmitError('');
                }}
                isSubmitting={isSubmitting}
            />
            <LiabilityEntryModal
                isOpen={isLiabilityModalOpen}
                initialValues={editingLiability}
                categories={liabilityCategories}
                onSubmit={handleSubmitLiability}
                onClose={() => {
                    if (isSubmitting) return;
                    setIsLiabilityModalOpen(false);
                    setEditingLiability(null);
                }}
                isSubmitting={isSubmitting}
            />

            {error && (
                <div className="rounded-[1.75rem] border border-rose-200 bg-rose-50 p-5 text-sm text-rose-800 shadow-sm">
                    <div className="flex items-start gap-3">
                        <AlertCircle size={18} className="mt-0.5 shrink-0" />
                        <div>
                            <p className="font-semibold">We could not load your debt plan.</p>
                            <p className="mt-1">{error}</p>
                        </div>
                    </div>
                </div>
            )}

            <DebtSummaryCards summary={summary} />

            <div className="space-y-6">
                <div className="flex flex-col gap-4 rounded-[2rem] border border-slate-200 bg-white px-6 py-6 shadow-sm lg:flex-row lg:items-start lg:justify-between">
                    <div className="max-w-3xl">
                        <p className="text-sm font-semibold uppercase tracking-[0.25em] text-primary-700">Your debts</p>
                        <h2 className="mt-3 text-3xl font-extrabold tracking-tight text-slate-950">Stay clear on what you owe and how you are progressing.</h2>
                        <p className="mt-3 text-sm leading-7 text-slate-600 sm:text-base">
                            Keep balances, lenders, repayment amounts, and due dates in one place so your next debt decision feels more deliberate and less stressful.
                        </p>
                    </div>
                    <button
                        type="button"
                        onClick={() => {
                            setEditingLiability(null);
                            setIsLiabilityModalOpen(true);
                        }}
                        className="inline-flex h-fit items-center gap-2 rounded-xl bg-primary-600 px-4 py-2 text-sm font-semibold text-white transition-colors hover:bg-primary-700"
                    >
                        Add Liability
                    </button>
                </div>

                <div className="rounded-[2rem] border border-slate-200 bg-white px-6 py-5 shadow-sm">
                    <div className="flex items-start gap-3">
                        <ShieldCheck className="mt-1 h-5 w-5 text-emerald-600" />
                        <div>
                            <h3 className="font-bold text-slate-900">Repayment focus</h3>
                            <p className="mt-2 text-sm leading-6 text-slate-600">
                                Add each debt clearly, then use this space to follow balances, repayment commitments, and the progress you are making over time.
                            </p>
                        </div>
                    </div>
                </div>

                {submitError && <div className="rounded-3xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800 shadow-sm">{submitError}</div>}

                <div className="space-y-4">
                    <div className="flex items-center gap-2 border-b border-slate-200 pb-2">
                        <button
                            type="button"
                            onClick={() => setActiveTab('debts')}
                            className={`rounded-lg px-3 py-2 text-sm font-semibold ${activeTab === 'debts' ? 'bg-primary-600 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
                        >
                            Debts
                        </button>
                        <button
                            type="button"
                            onClick={() => setActiveTab('liabilities')}
                            className={`rounded-lg px-3 py-2 text-sm font-semibold ${activeTab === 'liabilities' ? 'bg-primary-600 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
                        >
                            Liabilities
                        </button>
                    </div>
                    {activeTab === 'debts' ? (
                        <>
                            <div>
                                <p className="text-sm font-semibold uppercase tracking-[0.25em] text-primary-700">Active debts</p>
                                <h3 className="mt-2 text-2xl font-extrabold text-slate-950">Accounts you are currently managing</h3>
                            </div>
                            <DebtList
                                debts={debts}
                                onEdit={(debt) => {
                                    setEditingDebt(debt);
                                    setSubmitError('');
                                    setIsModalOpen(true);
                                }}
                                onDelete={handleDelete}
                                deletingId={deletingId}
                            />
                        </>
                    ) : (
                        <>
                            <div>
                                <p className="text-sm font-semibold uppercase tracking-[0.25em] text-primary-700">Active liabilities</p>
                                <h3 className="mt-2 text-2xl font-extrabold text-slate-950">Other obligations impacting your net worth</h3>
                            </div>
                            <LiabilitySimpleList
                                liabilities={liabilities}
                                onEdit={(liability) => {
                                    setEditingLiability(liability);
                                    setSubmitError('');
                                    setIsLiabilityModalOpen(true);
                                }}
                                onDelete={handleDeleteLiability}
                                deletingId={deletingId}
                            />
                        </>
                    )}
                </div>
            </div>
        </div>
    );
};

const LiabilitySimpleList = ({ liabilities, onEdit, onDelete, deletingId }) => {
    if (!liabilities.length) {
        return (
            <div className="rounded-3xl border border-dashed border-gray-300 bg-white/80 p-8 text-center shadow-sm">
                <h3 className="text-xl font-bold text-gray-900">No liabilities yet</h3>
                <p className="mt-2 text-sm text-gray-600">Add liabilities here so Net Worth gives a complete picture.</p>
            </div>
        );
    }

    return (
        <div className="space-y-3">
            {liabilities.map((liability) => (
                <article key={liability.uuid} className="rounded-2xl border border-slate-200 bg-white p-4">
                    <div className="flex items-start justify-between gap-4">
                        <div>
                            <h4 className="text-lg font-bold text-slate-900">{liability.name}</h4>
                            <p className="text-sm text-slate-500">{liability.categoryName}</p>
                            <p className="mt-1 text-sm text-slate-600">{liability.creditor || 'No creditor set'}</p>
                        </div>
                        <div className="text-right">
                            <p className="text-lg font-bold text-rose-600">KES {Number(liability.amount || 0).toLocaleString()}</p>
                            <p className="text-xs text-slate-500">{liability.statusDisplay || liability.status}</p>
                            <div className="mt-2 flex gap-2">
                                <button onClick={() => onEdit(liability)} className="rounded-lg border border-slate-300 px-2 py-1 text-xs font-semibold text-slate-700">Edit</button>
                                <button
                                    onClick={() => onDelete(liability.uuid)}
                                    disabled={deletingId === liability.uuid}
                                    className="rounded-lg border border-rose-200 px-2 py-1 text-xs font-semibold text-rose-700 disabled:opacity-60"
                                >
                                    {deletingId === liability.uuid ? 'Removing...' : 'Delete'}
                                </button>
                            </div>
                        </div>
                    </div>
                </article>
            ))}
        </div>
    );
};

const LiabilityEntryModal = ({ isOpen, initialValues, categories, onSubmit, onClose, isSubmitting }) => {
    const [formValues, setFormValues] = useState({
        name: '',
        categoryId: '',
        amount: '',
        dueDate: '',
        creditor: '',
        status: 'ACTIVE',
        includeInNetWorth: true,
        notes: '',
        currency: 'KES',
    });

    useEffect(() => {
        if (!isOpen) return;
        if (initialValues) {
            setFormValues({
                name: initialValues.name || '',
                categoryId: initialValues.category || '',
                amount: initialValues.amount || '',
                dueDate: initialValues.dueDate || '',
                creditor: initialValues.creditor || '',
                status: initialValues.status || 'ACTIVE',
                includeInNetWorth: initialValues.includeInNetWorth !== false,
                notes: initialValues.notes || '',
                currency: initialValues.currency || 'KES',
            });
            return;
        }
        const firstCategoryId = categories?.[0]?.categoryId || '';
        setFormValues({
            name: '',
            categoryId: firstCategoryId,
            amount: '',
            dueDate: '',
            creditor: '',
            status: 'ACTIVE',
            includeInNetWorth: true,
            notes: '',
            currency: 'KES',
        });
    }, [isOpen, initialValues, categories]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/45 px-4 py-6 backdrop-blur-[2px]">
            <div className="w-full max-w-lg overflow-hidden rounded-[1.15rem] bg-white shadow-2xl">
                <div className="flex items-center justify-between bg-primary-700 px-4 py-3 text-white">
                    <h2 className="text-base font-bold">{initialValues ? 'Update liability' : 'Add new liability'}</h2>
                    <button type="button" onClick={onClose} className="inline-flex h-8 w-8 items-center justify-center rounded-full bg-white/10 hover:bg-white/20">
                        x
                    </button>
                </div>
                <form
                    onSubmit={(event) => {
                        event.preventDefault();
                        onSubmit(formValues);
                    }}
                    className="space-y-3 p-4"
                >
                    <input
                        value={formValues.name}
                        onChange={(e) => setFormValues((prev) => ({ ...prev, name: e.target.value }))}
                        placeholder="Liability name"
                        className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                        required
                    />
                    <select
                        value={formValues.categoryId}
                        onChange={(e) => setFormValues((prev) => ({ ...prev, categoryId: Number(e.target.value) }))}
                        className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                        required
                    >
                        {categories.map((category) => (
                            <option key={category.uuid || category.id} value={category.categoryId}>{category.name}</option>
                        ))}
                    </select>
                    <input
                        type="number"
                        value={formValues.amount}
                        onChange={(e) => setFormValues((prev) => ({ ...prev, amount: e.target.value }))}
                        placeholder="Amount"
                        className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                        required
                    />
                    <input
                        type="date"
                        value={formValues.dueDate}
                        onChange={(e) => setFormValues((prev) => ({ ...prev, dueDate: e.target.value }))}
                        className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                    />
                    <input
                        value={formValues.creditor}
                        onChange={(e) => setFormValues((prev) => ({ ...prev, creditor: e.target.value }))}
                        placeholder="Creditor"
                        className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                    />
                    <textarea
                        value={formValues.notes}
                        onChange={(e) => setFormValues((prev) => ({ ...prev, notes: e.target.value }))}
                        placeholder="Notes"
                        className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
                    />
                    <div className="flex justify-end gap-2">
                        <button type="button" onClick={onClose} className="rounded-lg border border-slate-300 px-3 py-2 text-sm">Cancel</button>
                        <button type="submit" disabled={isSubmitting} className="rounded-lg bg-primary-600 px-3 py-2 text-sm font-semibold text-white">
                            {isSubmitting ? 'Saving...' : initialValues ? 'Update Liability' : 'Add Liability'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default DebtManagerPanel;

import React from 'react';
import ScoreGauge from './ScoreGauge';

const ComponentBreakdown = ({ components, overallScore, onComponentClick = null }) => {
    const getScoreColor = (score) => {
        if (score >= 80) return 'text-green-600';
        if (score >= 60) return 'text-blue-600';
        if (score >= 40) return 'text-yellow-600';
        return 'text-red-600';
    };

    const getScoreBg = (score) => {
        if (score >= 80) return 'bg-green-50 border-green-200 hover:border-green-300 hover:bg-green-100';
        if (score >= 60) return 'bg-blue-50 border-blue-200 hover:border-blue-300 hover:bg-blue-100';
        if (score >= 40) return 'bg-yellow-50 border-yellow-200 hover:border-yellow-300 hover:bg-yellow-100';
        return 'bg-red-50 border-red-200 hover:border-red-300 hover:bg-red-100';
    };

    const formatDataValue = (value) => {
        if (typeof value === 'number') {
            return value % 1 === 0 ? value : value.toFixed(1);
        }
        return value;
    };

    const formatDataKey = (key) => {
        return key
            .replace(/_/g, ' ')
            .replace(/\b\w/g, (char) => char.toUpperCase());
    };

    return (
        <div className="rounded-[2rem] border border-slate-200 bg-white p-6 shadow-sm">
            <div className="mb-6">
                <h3 className="text-xl font-bold text-slate-950 sm:text-2xl">Score Breakdown</h3>
                <p className="mt-1 text-sm text-slate-600">
                    Detailed view of each component contributing to your overall score
                </p>
            </div>

            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                {components && components.map((component) => (
                    <div
                        key={component.key}
                        onClick={() => onComponentClick && onComponentClick(component)}
                        className={`group rounded-2xl border-2 p-5 transition-all ${
                            onComponentClick ? 'cursor-pointer' : ''
                        } ${getScoreBg(component.score)}`}
                    >
                        {/* Header */}
                        <div className="mb-4 flex items-start justify-between gap-3">
                            <div className="flex-1 min-w-0">
                                <h4 className="text-sm font-bold text-slate-950 truncate">
                                    {component.name}
                                </h4>
                                <p className="mt-1 text-xs leading-relaxed text-slate-600">
                                    {component.description}
                                </p>
                            </div>
                            <span className={`flex-shrink-0 text-2xl font-extrabold sm:text-3xl ${getScoreColor(component.score)}`}>
                                {component.score}
                            </span>
                        </div>

                        {/* Progress Bar */}
                        <div className="mb-3">
                            <ScoreGauge score={component.score} height="h-2" animated />
                        </div>

                        {/* Stats */}
                        <div className="mb-3 flex items-center justify-between text-xs">
                            <span className="font-semibold text-slate-600">
                                Weight: {component.weight}%
                            </span>
                            <span className={`rounded-full px-2 py-0.5 font-bold ${
                                component.score >= 80 ? 'bg-green-100 text-green-700' :
                                component.score >= 60 ? 'bg-blue-100 text-blue-700' :
                                component.score >= 40 ? 'bg-yellow-100 text-yellow-700' :
                                'bg-red-100 text-red-700'
                            }`}>
                                Grade: {component.grade}
                            </span>
                        </div>

                        {/* Component Specific Data */}
                        {component.data && Object.keys(component.data).length > 0 && (
                            <div className="space-y-1.5 border-t border-slate-200 pt-3">
                                {Object.entries(component.data).slice(0, 2).map(([key, value]) => (
                                    <div key={key} className="flex justify-between text-xs">
                                        <span className="text-slate-600 truncate pr-2">
                                            {formatDataKey(key)}:
                                        </span>
                                        <span className="font-semibold text-slate-950 flex-shrink-0">
                                            {formatDataValue(value)}
                                        </span>
                                    </div>
                                ))}
                            </div>
                        )}

                        {/* Click indicator */}
                        {onComponentClick && (
                            <div className="mt-3 flex items-center justify-center text-xs font-medium text-slate-500 opacity-0 transition-opacity group-hover:opacity-100">
                                Click for details
                                <svg className="ml-1 h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                                </svg>
                            </div>
                        )}
                    </div>
                ))}
            </div>
        </div>
    );
};

export default ComponentBreakdown;

import React, { useEffect, useState, useCallback } from 'react';
import { useFinancialHealth } from '../../../contexts/FinancialHealthContext';
import HealthScoreCard from './HealthScoreCard';
import ComponentBreakdown from './ComponentBreakdown';
import ScoreHistoryChart from './ScoreHistoryChart';
import InsightsPanel from './InsightsPanel';
import ComponentDetailModal from './ComponentDetailModal';

const FinancialHealthDashboard = () => {
    const {
        healthScore,
        scoreHistory,
        scoreBreakdown,
        insights,
        loading,
        error,
        lastRefresh,
        fetchHealthScore,
        fetchScoreHistory,
        fetchScoreBreakdown,
        fetchInsights,
        refreshAll
    } = useFinancialHealth();

    const [refreshing, setRefreshing] = useState(false);
    const [selectedComponent, setSelectedComponent] = useState(null);
    const [lastTriggerTimestamp, setLastTriggerTimestamp] = useState(null);

    // Initial data load
    useEffect(() => {
        const loadInitialData = async () => {
            try {
                await Promise.all([
                    fetchHealthScore(),
                    fetchScoreHistory(6),
                    fetchScoreBreakdown(),
                    fetchInsights()
                ]);
            } catch (err) {
                console.error('Failed to load financial health data:', err);
            }
        };

        loadInitialData();
    }, [fetchHealthScore, fetchScoreHistory, fetchScoreBreakdown, fetchInsights]);

    // Listen for refresh triggers from other components
    useEffect(() => {
        const handleRefreshRequest = () => {
            console.log('Health refresh requested from external component');
            refreshAll(true);
        };

        const handleStorageChange = (e) => {
            if (e.key === 'healthRefreshTrigger') {
                let triggerPayload = null;
                try {
                    triggerPayload = JSON.parse(e.newValue || '{}');
                } catch {
                    triggerPayload = { timestamp: Number(e.newValue) || Date.now() };
                }

                const nextTimestamp = Number(triggerPayload?.timestamp) || Date.now();
                if (nextTimestamp !== lastTriggerTimestamp) {
                    setLastTriggerTimestamp(nextTimestamp);
                    handleRefreshRequest();
                }
            }
        };

        // Listen for custom event
        window.addEventListener('healthRefreshRequested', handleRefreshRequest);
        
        // Listen for localStorage changes (works across tabs)
        window.addEventListener('storage', handleStorageChange);

        return () => {
            window.removeEventListener('healthRefreshRequested', handleRefreshRequest);
            window.removeEventListener('storage', handleStorageChange);
        };
    }, [lastTriggerTimestamp, refreshAll]);

    // Auto-refresh every 5 minutes if on the page
    useEffect(() => {
        const intervalId = setInterval(() => {
            if (document.visibilityState === 'visible') {
                console.log('Auto-refreshing health score (5 min interval)');
                refreshAll(true);
            }
        }, 5 * 60 * 1000); // 5 minutes

        return () => clearInterval(intervalId);
    }, [refreshAll]);

    const handleRefresh = async () => {
        setRefreshing(true);
        try {
            await refreshAll(true);
        } catch (err) {
            console.error('Failed to refresh:', err);
        } finally {
            setRefreshing(false);
        }
    };

    if (loading && !healthScore) {
        return (
            <div className="flex min-h-screen items-center justify-center bg-[linear-gradient(180deg,_#f8fafc_0%,_#eef4f8_100%)]">
                <div className="flex flex-col items-center gap-4">
                    <svg className="h-12 w-12 animate-spin text-primary-600" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                    </svg>
                    <p className="text-sm font-medium text-slate-600">Calculating your financial health...</p>
                </div>
            </div>
        );
    }

    if (error && !healthScore) {
        return (
            <div className="min-h-screen bg-[linear-gradient(180deg,_#f8fafc_0%,_#eef4f8_100%)]">
                <div className="px-4 py-8">
                    <div className="mx-auto max-w-2xl">
                        <div className="rounded-2xl border-2 border-red-200 bg-red-50 p-6">
                            <div className="flex items-start gap-4">
                                <svg className="h-6 w-6 flex-shrink-0 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                </svg>
                                <div className="flex-1">
                                    <h3 className="text-sm font-semibold text-red-900">Unable to load financial health data</h3>
                                    <p className="mt-1 text-sm text-red-700">{error}</p>
                                    <button
                                        onClick={() => fetchHealthScore()}
                                        className="mt-4 rounded-lg bg-red-600 px-4 py-2 text-sm font-semibold text-white hover:bg-red-700"
                                    >
                                        Try Again
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[linear-gradient(180deg,_#f8fafc_0%,_#eef4f8_100%)]">
            <div className="px-4 py-4 sm:px-6 sm:py-6 lg:px-8 lg:py-8">
                <div className="mx-auto max-w-7xl space-y-6">
                    {/* Header Section */}
                    <section className="rounded-[2rem] border border-slate-200 bg-white px-6 py-6 shadow-sm">
                        <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                            <div className="flex-1">
                                <p className="text-sm font-semibold uppercase tracking-[0.3em] text-primary-700">
                                    Financial Health
                                </p>
                                <h1 className="mt-3 text-3xl font-extrabold tracking-tight text-slate-950 sm:text-4xl">
                                    Your complete financial wellness snapshot
                                </h1>
                                <p className="mt-3 max-w-3xl text-sm leading-7 text-slate-600 sm:text-base">
                                    Track your financial health score across key metrics including savings rate, debt burden, emergency fund, budget adherence, and net worth trend.
                                </p>
                                {lastRefresh && (
                                    <p className="mt-2 text-xs text-slate-500">
                                        Last updated: {new Date(lastRefresh).toLocaleTimeString()}
                                    </p>
                                )}
                            </div>
                            <button
                                onClick={handleRefresh}
                                disabled={refreshing}
                                className="flex items-center gap-2 rounded-xl bg-primary-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition-all hover:bg-primary-700 disabled:opacity-50 sm:px-5 sm:py-3"
                            >
                                <svg
                                    className={`h-4 w-4 ${refreshing ? 'animate-spin' : ''}`}
                                    fill="none"
                                    viewBox="0 0 24 24"
                                    stroke="currentColor"
                                >
                                    <path
                                        strokeLinecap="round"
                                        strokeLinejoin="round"
                                        strokeWidth={2}
                                        d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
                                    />
                                </svg>
                                {refreshing ? 'Refreshing...' : 'Refresh'}
                            </button>
                        </div>
                    </section>

                    {/* Main Score Card */}
                    {healthScore && (
                        <HealthScoreCard
                            score={healthScore.overall_score}
                            status={healthScore.status}
                            statusDisplay={healthScore.status_display}
                            change={healthScore.change_from_previous}
                            scoreDate={healthScore.score_date}
                        />
                    )}

                    {/* Components Breakdown Grid */}
                    {scoreBreakdown && (
                        <ComponentBreakdown
                            components={scoreBreakdown.components}
                            overallScore={scoreBreakdown.overall.score}
                            onComponentClick={setSelectedComponent}
                        />
                    )}

                    {/* History Chart and Insights Side by Side */}
                    <div className="grid gap-6 lg:grid-cols-2">
                        {scoreHistory && (
                            <ScoreHistoryChart
                                history={scoreHistory.history}
                                trend={scoreHistory.trend}
                                stats={scoreHistory.stats}
                            />
                        )}

                        {insights && (
                            <InsightsPanel
                                insights={insights.insights}
                                priorityActions={insights.priority_actions}
                                summary={insights.summary}
                                score={insights.score}
                            />
                        )}
                    </div>
                </div>
            </div>

            {/* Component Detail Modal */}
            {selectedComponent && (
                <ComponentDetailModal
                    component={selectedComponent}
                    onClose={() => setSelectedComponent(null)}
                />
            )}
        </div>
    );
};

export default FinancialHealthDashboard;

import React, { useState, useMemo } from 'react';

const InsightsPanel = ({ insights, priorityActions, summary, score }) => {
    const [activeTab, setActiveTab] = useState('all');

    const getInsightIcon = (type) => {
        switch (type) {
            case 'POSITIVE':
                return (
                    <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                );
            case 'WARNING':
                return (
                    <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                    </svg>
                );
            case 'CRITICAL':
                return (
                    <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                );
            case 'TIP':
                return (
                    <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
                    </svg>
                );
            default:
                return (
                    <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                );
        }
    };

    const getInsightColors = (type) => {
        switch (type) {
            case 'POSITIVE':
                return {
                    bg: 'bg-green-50',
                    border: 'border-green-200',
                    text: 'text-green-700',
                    icon: 'text-green-600',
                    hover: 'hover:bg-green-100'
                };
            case 'WARNING':
                return {
                    bg: 'bg-yellow-50',
                    border: 'border-yellow-200',
                    text: 'text-yellow-700',
                    icon: 'text-yellow-600',
                    hover: 'hover:bg-yellow-100'
                };
            case 'CRITICAL':
                return {
                    bg: 'bg-red-50',
                    border: 'border-red-200',
                    text: 'text-red-700',
                    icon: 'text-red-600',
                    hover: 'hover:bg-red-100'
                };
            case 'TIP':
                return {
                    bg: 'bg-blue-50',
                    border: 'border-blue-200',
                    text: 'text-blue-700',
                    icon: 'text-blue-600',
                    hover: 'hover:bg-blue-100'
                };
            default:
                return {
                    bg: 'bg-slate-50',
                    border: 'border-slate-200',
                    text: 'text-slate-700',
                    icon: 'text-slate-600',
                    hover: 'hover:bg-slate-100'
                };
        }
    };

    const filteredInsights = useMemo(() => {
        if (!insights) return { positive: [], warnings: [], critical: [], tips: [] };

        if (activeTab === 'all') {
            return insights;
        }

        return {
            positive: activeTab === 'positive' ? insights.positive : [],
            warnings: activeTab === 'warnings' ? insights.warnings : [],
            critical: activeTab === 'critical' ? insights.critical : [],
            tips: activeTab === 'tips' ? insights.tips : []
        };
    }, [insights, activeTab]);

    const allInsights = useMemo(() => {
        if (!filteredInsights) return [];
        
        return [
            ...filteredInsights.critical || [],
            ...filteredInsights.warnings || [],
            ...filteredInsights.positive || [],
            ...filteredInsights.tips || []
        ];
    }, [filteredInsights]);

    const tabs = [
        { id: 'all', label: 'All', count: summary?.positive_count + summary?.warnings_count + summary?.critical_count + summary?.tips_count || 0 },
        { id: 'critical', label: 'Critical', count: summary?.critical_count || 0 },
        { id: 'warnings', label: 'Warnings', count: summary?.warnings_count || 0 },
        { id: 'positive', label: 'Positive', count: summary?.positive_count || 0 },
        { id: 'tips', label: 'Tips', count: summary?.tips_count || 0 }
