import React, { useState, useMemo } from 'react';

const ScoreHistoryChart = ({ history, trend, stats }) => {
    const [selectedPeriod, setSelectedPeriod] = useState(6);
    const [hoveredPoint, setHoveredPoint] = useState(null);

    // Filter history based on selected period
    const filteredHistory = useMemo(() => {
        if (!history) return [];
        return history.slice(0, selectedPeriod * 4); // Roughly weekly data
    }, [history, selectedPeriod]);

    // Calculate chart dimensions and scales - FIXED PADDING
    const chartWidth = 100; 
    const chartHeight = 200; 
    const padding = { top: 20, right: 10, bottom: 30, left: 35 }; // Increased left padding for labels

    const points = useMemo(() => {
        if (!filteredHistory || filteredHistory.length === 0) return [];

        const maxScore = 100;
        const minScore = 0;
        const scoreRange = maxScore - minScore;

        return filteredHistory.map((item, index) => {
            const x = (index / (filteredHistory.length - 1)) * (chartWidth - padding.left - padding.right) + padding.left;
            const y = chartHeight - padding.bottom - ((item.overall_score - minScore) / scoreRange) * (chartHeight - padding.top - padding.bottom);
            return { x, y, ...item };
        }).reverse();
    }, [filteredHistory, chartHeight, chartWidth, padding]);

    // Generate SVG path
    const pathData = useMemo(() => {
        if (points.length === 0) return '';
        
        let path = `M ${points[0].x} ${points[0].y}`;
        
        // Create smooth curve using quadratic bezier curves
        for (let i = 1; i < points.length; i++) {
            const prevPoint = points[i - 1];
            const currentPoint = points[i];
            const midX = (prevPoint.x + currentPoint.x) / 2;
            
            path += ` Q ${prevPoint.x} ${prevPoint.y} ${midX} ${(prevPoint.y + currentPoint.y) / 2}`;
            path += ` Q ${currentPoint.x} ${currentPoint.y} ${currentPoint.x} ${currentPoint.y}`;
        }
        
        return path;
    }, [points]);

    // Generate area path (for gradient fill)
    const areaPath = useMemo(() => {
        if (points.length === 0) return '';
        
        let path = pathData;
        const lastPoint = points[points.length - 1];
        const firstPoint = points[0];
        
        path += ` L ${lastPoint.x} ${chartHeight - padding.bottom}`;
        path += ` L ${firstPoint.x} ${chartHeight - padding.bottom}`;
        path += ' Z';
        
        return path;
    }, [pathData, points, chartHeight, padding]);

    const getTrendColor = () => {
        if (!trend) return 'text-slate-600';
        if (trend.direction === 'up') return 'text-green-600';
        if (trend.direction === 'down') return 'text-red-600';
        return 'text-slate-600';
    };

    const getTrendIcon = () => {
        if (!trend) return null;
        
        if (trend.direction === 'up') {
            return (
                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
                </svg>
            );
        } else if (trend.direction === 'down') {
            return (
                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 17h8m0 0V9m0 8l-8-8-4 4-6-6" />
                </svg>
            );
        }
        
        return (
            <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 12h14" />
            </svg>
        );
    };

    if (!history || history.length === 0) {
        return (
            <div className="rounded-[2rem] border border-slate-200 bg-white p-6 shadow-sm">
                <h3 className="text-xl font-bold text-slate-950">Score History</h3>
                <div className="mt-6 flex flex-col items-center justify-center py-12">
                    <svg className="h-16 w-16 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                    </svg>
                    <p className="mt-4 text-sm font-medium text-slate-600">No historical data yet</p>
                    <p className="mt-1 text-xs text-slate-500">Check back after a few score calculations</p>
                </div>
            </div>
        );
    }

    return (
        <div className="rounded-[2rem] border border-slate-200 bg-white p-6 shadow-sm">
            {/* Header */}
            <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                <div>
                    <h3 className="text-xl font-bold text-slate-950">Score History</h3>
                    <p className="mt-1 text-sm text-slate-600">Track your financial health over time</p>
                </div>

                {/* Period Selector */}
                <div className="flex gap-2">
                    {[3, 6, 12, 24].map((months) => (
                        <button
                            key={months}
                            onClick={() => setSelectedPeriod(months)}
                            className={`rounded-lg px-3 py-1.5 text-xs font-semibold transition-all ${
                                selectedPeriod === months
                                    ? 'bg-primary-600 text-white shadow-sm'
                                    : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                            }`}
                        >
                            {months}M
                        </button>
                    ))}
                </div>
            </div>

            {/* Chart */}
            <div className="relative mb-6" style={{ height: `${chartHeight}px` }}>
                <svg
                    width="100%"
                    height="100%"
                    viewBox={`0 0 ${chartWidth} ${chartHeight}`}
                    preserveAspectRatio="none"
                    className="overflow-visible"
                >
                    {/* Gradient definition */}
                    <defs>
                        <linearGradient id="scoreGradient" x1="0%" y1="0%" x2="0%" y2="100%">
                            <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.3" />
                            <stop offset="100%" stopColor="#3b82f6" stopOpacity="0.05" />
                        </linearGradient>
                    </defs>

                    {/* Horizontal grid lines with FIXED Y-axis labels */}
                    {[0, 25, 50, 75, 100].map((value) => {
                        const y = chartHeight - padding.bottom - (value / 100) * (chartHeight - padding.top - padding.bottom);
                        return (
                            <g key={value}>
                                {/* Grid line */}
                                <line
                                    x1={padding.left}
                                    y1={y}
                                    x2={chartWidth - padding.right}
                                    y2={y}
                                    stroke="#e2e8f0"
                                    strokeWidth="1"
                                    strokeDasharray="4 4"
                                />
                                {/* Y-axis label - FIXED POSITION */}
                                <text
                                    x={padding.left - 8}
                                    y={y}
                                    fontSize="10"
                                    fill="#64748b"
                                    textAnchor="end"
                                    dominantBaseline="middle"
                                    style={{ userSelect: 'none' }}
                                >
                                    {value}
                                </text>
                            </g>
                        );
                    })}

                    {/* Area fill */}
                    {areaPath && (
                        <path
                            d={areaPath}
                            fill="url(#scoreGradient)"
                        />
                    )}

                    {/* Line path */}
                    {pathData && (
                        <path
                            d={pathData}
                            fill="none"
                            stroke="#3b82f6"
                            strokeWidth="3"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                        />
                    )}

                    {/* Data points */}
                    {points.map((point, index) => (
                        <g key={index}>
                            <circle
                                cx={point.x}
                                cy={point.y}
                                r="4"
                                fill="white"
                                stroke="#3b82f6"
                                strokeWidth="2"
                                className="cursor-pointer transition-all hover:r-6"
                                onMouseEnter={() => setHoveredPoint(point)}
                                onMouseLeave={() => setHoveredPoint(null)}
                            />
                            {hoveredPoint === point && (
                                <g>
                                    <rect
                                        x={point.x - 35}
                                        y={point.y - 45}
                                        width="70"
                                        height="35"
                                        rx="8"
                                        fill="#1e293b"
                                        opacity="0.95"
                                    />
                                    <text
                                        x={point.x}
                                        y={point.y - 30}
                                        fontSize="11"
                                        fontWeight="bold"
                                        fill="white"
                                        textAnchor="middle"
                                    >
                                        Score: {point.overall_score}
                                    </text>
                                    <text
                                        x={point.x}
                                        y={point.y - 16}
                                        fontSize="9"
                                        fill="#cbd5e1"
                                        textAnchor="middle"
                                    >
                                        {new Date(point.score_date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                                    </text>
                                </g>
                            )}
                        </g>
                    ))}
                </svg>
            </div>

            {/* Trend Stats */}
            {trend && (
                <div className="mb-4 flex items-center justify-center gap-2 rounded-xl bg-slate-50 p-3">
                    <span className={`flex items-center gap-1 font-semibold ${getTrendColor()}`}>
                        {getTrendIcon()}
                        {trend.percentage_change > 0 ? '+' : ''}{trend.percentage_change}%
                    </span>
                    <span className="text-sm text-slate-600">
                        ({trend.points_change > 0 ? '+' : ''}{trend.points_change} points)
                    </span>
                </div>
            )}

            {/* Statistics */}
            {stats && (
                <div className="grid grid-cols-3 gap-4">
                    <div className="text-center">
                        <p className="text-2xl font-bold text-green-600">{stats.best_score}</p>
                        <p className="text-xs text-slate-600">Best Score</p>
                    </div>
                    <div className="text-center">
                        <p className="text-2xl font-bold text-slate-950">{stats.average_score}</p>
                        <p className="text-xs text-slate-600">Average</p>
                    </div>
                    <div className="text-center">
                        <p className="text-2xl font-bold text-red-600">{stats.worst_score}</p>
                        <p className="text-xs text-slate-600">Worst Score</p>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ScoreHistoryChart;

import React from 'react';

const CategoryPieChart = ({ data, title, type = 'income' }) => {
    if (!data || data.length === 0) return null;

    const createPieSlice = (percentage, startAngle, color) => {
        const angle = (percentage / 100) * 360;
        const endAngle = startAngle + angle;
        const largeArcFlag = angle > 180 ? 1 : 0;
        
        const startX = 50 + 45 * Math.cos((Math.PI * startAngle) / 180);
        const startY = 50 + 45 * Math.sin((Math.PI * startAngle) / 180);
        const endX = 50 + 45 * Math.cos((Math.PI * endAngle) / 180);
        const endY = 50 + 45 * Math.sin((Math.PI * endAngle) / 180);
        
        return `M 50 50 L ${startX} ${startY} A 45 45 0 ${largeArcFlag} 1 ${endX} ${endY} Z`;
    };

    const formatCurrency = (amount) => {
        return new Intl.NumberFormat('en-US', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }).format(amount);
    };

    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
            <h3 className="text-lg font-bold text-gray-900 mb-6">{title}</h3>
            
            {/* Pie Chart */}
            <div className="flex justify-center mb-6">
                <svg width="200" height="200" viewBox="0 0 100 100" className="drop-shadow-md">
                    {data.map((item, index) => {
                        let startAngle = -90;
                        for (let i = 0; i < index; i++) {
                            startAngle += (data[i].percentage / 100) * 360;
                        }
                        const path = createPieSlice(item.percentage, startAngle, item.color);
                        return (
                            <g key={index}>
                                <path
                                    d={path}
                                    fill={item.color}
                                    stroke="white"
                                    strokeWidth="1"
                                    className="transition-all duration-300 hover:opacity-80 cursor-pointer"
                                />
                            </g>
                        );
                    })}
                </svg>
            </div>

            {/* Legend with Bars */}
            <div className="space-y-3">
                {data.map((item, index) => (
                    <div key={index}>
                        <div className="flex items-center justify-between mb-1.5">
                            <div className="flex items-center gap-2 flex-1 min-w-0">
                                <span 
                                    className="w-3 h-3 rounded-sm shrink-0" 
                                    style={{ backgroundColor: item.color }}
                                />
                                <div className="flex-1 min-w-0">
                                    <p className="text-sm font-semibold text-gray-900 truncate">{item.category}</p>
                                    <p className="text-xs text-gray-500">{item.count} {item.count === 1 ? 'transaction' : 'transactions'}</p>
                                </div>
                            </div>
                            <div className="text-right ml-2">
                                <p className="text-sm font-bold text-gray-900">
                                    {formatCurrency(item.amount)}
                                </p>
                                <p className={`text-xs font-semibold ${type === 'income' ? 'text-green-600' : 'text-red-600'}`}>
                                    {item.percentage}%
                                </p>
                            </div>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-1.5 overflow-hidden">
                            <div
                                className="h-full rounded-full transition-all duration-500"
                                style={{ 
                                    width: `${item.percentage}%`,
                                    backgroundColor: item.color 
                                }}
                            />
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default CategoryPieChart;

import React, { useState, useEffect } from 'react';
import { useIncome } from '../../../contexts/IncomeContext';
import { X } from 'lucide-react';

const IncomeForm = ({ income, onClose, onSuccess }) => {
    const { createIncome, updateIncome, addQuickIncome, fetchIncomes, fetchSummary, categories } = useIncome();
    const [formData, setFormData] = useState({
        category: '',
        amount: '',
        description: '',
        source: '',
        income_date: new Date().toISOString().split('T')[0],
        frequency: 'ONE_TIME',
        is_recurring: false,
        recurring_end_date: '',
        status: 'RECEIVED',
        is_taxable: false,
        notes: ''
    });
    const [submitting, setSubmitting] = useState(false);
    const [error, setError] = useState('');

    const frequencyOptions = [
        { value: 'ONE_TIME', label: 'One-time' },
        { value: 'DAILY', label: 'Daily' },
        { value: 'WEEKLY', label: 'Weekly' },
        { value: 'BIWEEKLY', label: 'Bi-weekly' },
        { value: 'MONTHLY', label: 'Monthly' },
        { value: 'QUARTERLY', label: 'Quarterly' },
        { value: 'YEARLY', label: 'Yearly' }
    ];

    const statusOptions = [
        { value: 'RECEIVED', label: 'Received', color: 'text-green-700' },
        { value: 'EXPECTED', label: 'Expected', color: 'text-blue-700' },
        { value: 'CANCELLED', label: 'Cancelled', color: 'text-red-700' }
    ];

    useEffect(() => {
        if (income) {
            setFormData({
                category: income.category || '',
                amount: income.amount || '',
                description: income.description || '',
                source: income.source || '',
                income_date: income.income_date || new Date().toISOString().split('T')[0],
                frequency: income.frequency || 'ONE_TIME',
                is_recurring: income.is_recurring || false,
                recurring_end_date: income.recurring_end_date || '',
                status: income.status || 'RECEIVED',
                is_taxable: income.is_taxable || false,
                notes: income.notes || ''
            });
        }
    }, [income]);

    const handleChange = (field, value) => {
        setFormData(prev => {
            const updated = { ...prev, [field]: value };

            // If toggling recurring off, reset frequency to ONE_TIME
            if (field === 'is_recurring' && !value) {
                updated.frequency = 'ONE_TIME';
                updated.recurring_end_date = '';
            }

            // If toggling recurring on and frequency is ONE_TIME, change to MONTHLY
            if (field === 'is_recurring' && value && prev.frequency === 'ONE_TIME') {
                updated.frequency = 'MONTHLY';
            }

            return updated;
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setSubmitting(true);

        try {
            const submitData = { ...formData };

            // Remove empty optional fields
            if (!submitData.source) delete submitData.source;
            if (!submitData.recurring_end_date) delete submitData.recurring_end_date;
            if (!submitData.notes) delete submitData.notes;

            if (income) {
                // When editing, exclude category (can't change after creation)
                delete submitData.category;
                await updateIncome(income.uuid, submitData);
            } else {
                // Use the quick endpoint for creation — it properly handles
                // UUID-based category lookups, unlike the regular /income/ endpoint
                // which expects an integer PK that the categories API doesn't provide.
                await addQuickIncome(submitData);
            }

            if (onSuccess) onSuccess();
            onClose();
        } catch (err) {
            setError(err.message || 'Failed to save income');
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50 backdrop-blur-sm">
            <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                {/* Header */}
                <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 rounded-t-2xl z-10">
                    <div className="flex items-center justify-between">
                        <h2 className="text-xl font-bold text-gray-900">
                            {income ? 'Edit Income' : 'Add New Income'}
                        </h2>
                        <button
                            onClick={onClose}
                            className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors duration-200"
                        >
                            <X size={20} />
                        </button>
                    </div>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="px-6 py-6 space-y-6">
                    {/* Error Alert */}
                    {error && (
                        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg text-sm">
                            {error}
                        </div>
                    )}

                    {/* Category Dropdown */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Income Category <span className="text-red-500">*</span>
                        </label>
                        <select
                            required
                            value={formData.category}
                            onChange={(e) => handleChange('category', e.target.value)}
                            className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                        >
                            <option value="">Select a category...</option>
                            {categories.map((cat) => (
                                <option key={cat.uuid} value={cat.uuid}>
                                    {cat.name}
                                </option>
                            ))}
                        </select>
                    </div>

                    {/* Amount and Date Row */}
                    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Amount <span className="text-red-500">*</span>
                            </label>
                            <div className="relative">
                                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 font-medium">
                                    KES
                                </span>
                                <input
                                    type="number"
                                    step="0.01"
                                    required
                                    value={formData.amount}
                                    onChange={(e) => handleChange('amount', e.target.value)}
                                    className="w-full pl-16 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                                    placeholder="0.00"
                                />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Date <span className="text-red-500">*</span>
                            </label>
                            <input
                                type="date"
                                required
                                value={formData.income_date}
                                onChange={(e) => handleChange('income_date', e.target.value)}
                                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                            />
                        </div>
                    </div>

                    {/* Description */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Description <span className="text-red-500">*</span>
                        </label>
                        <input
                            type="text"
                            required
                            value={formData.description}
                            onChange={(e) => handleChange('description', e.target.value)}
                            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                            placeholder="e.g., Monthly salary, Freelance project"
                        />
                    </div>

                    {/* Source */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Source (Optional)
                        </label>
                        <input
                            type="text"
                            value={formData.source}
                            onChange={(e) => handleChange('source', e.target.value)}
                            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                            placeholder="e.g., Company name, Client name"
                        />
                    </div>

                    {/* Status */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Status
                        </label>
                        <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
                            {statusOptions.map((option) => (
                                <button
                                    key={option.value}
                                    type="button"
                                    onClick={() => handleChange('status', option.value)}
                                    className={`py-3 px-4 rounded-lg border-2 font-medium transition-all duration-200 ${formData.status === option.value
                                            ? 'border-blue-500 bg-blue-50 text-blue-700'
                                            : 'border-gray-200 hover:border-gray-300 text-gray-700'
                                        }`}
                                >
                                    {option.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Recurring Toggle */}
                    <div className="bg-gray-50 rounded-lg p-4">
                        <label className="flex items-center gap-3 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={formData.is_recurring}
                                onChange={(e) => handleChange('is_recurring', e.target.checked)}
                                className="w-5 h-5 text-blue-600 rounded focus:ring-2 focus:ring-blue-500"
                            />
                            <div>
                                <span className="block text-sm font-medium text-gray-900">Recurring Income</span>
                                <span className="block text-xs text-gray-500">This income repeats regularly</span>
                            </div>
                        </label>

                        {/* Recurring Options */}
                        {formData.is_recurring && (
                            <div className="mt-4 space-y-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-2">
                                        Frequency
                                    </label>
                                    <select
                                        value={formData.frequency}
                                        onChange={(e) => handleChange('frequency', e.target.value)}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                                    >
                                        {frequencyOptions.filter(opt => opt.value !== 'ONE_TIME').map((option) => (
                                            <option key={option.value} value={option.value}>
                                                {option.label}
                                            </option>
                                        ))}
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-2">
                                        End Date (Optional)
                                    </label>
                                    <input
                                        type="date"
                                        value={formData.recurring_end_date}
                                        onChange={(e) => handleChange('recurring_end_date', e.target.value)}
                                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                                    />
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Taxable Toggle */}
                    <div>
                        <label className="flex items-center gap-3 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={formData.is_taxable}
                                onChange={(e) => handleChange('is_taxable', e.target.checked)}
                                className="w-5 h-5 text-blue-600 rounded focus:ring-2 focus:ring-blue-500"
                            />
                            <div>
                                <span className="block text-sm font-medium text-gray-900">Taxable Income</span>
                                <span className="block text-xs text-gray-500">This income is subject to tax</span>
                            </div>
                        </label>
                    </div>

                    {/* Notes */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Notes (Optional)
                        </label>
                        <textarea
                            value={formData.notes}
                            onChange={(e) => handleChange('notes', e.target.value)}
                            rows={3}
                            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200 resize-none"
                            placeholder="Any additional details..."
                        />
                    </div>

                    {/* Submit Buttons */}
                    <div className="flex gap-3 pt-4">
                        <button
                            type="submit"
                            disabled={submitting || !formData.category || !formData.amount || !formData.description}
                            className="flex-1 py-3 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed transition-colors duration-200 shadow-lg hover:shadow-xl"
                        >
                            {submitting ? 'Saving...' : income ? 'Update Income' : 'Add Income'}
                        </button>
                        <button
                            type="button"
                            onClick={onClose}
                            className="px-6 py-3 border border-gray-300 text-gray-700 font-semibold rounded-lg hover:bg-gray-50 transition-colors duration-200"
                        >
                            Cancel
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default IncomeForm;

import React from 'react';
import { TrendingUp, TrendingDown, DollarSign, RefreshCw, Calendar } from 'lucide-react';
import IncomeStatCard from './IncomeStatCard';

const IncomeSummary = ({ summary, loading }) => {
    if (!summary && !loading) {
        return null;
    }

    const currentMonth = summary?.current_month || {};
    const currency = summary?.currency || 'KES';
    const incomeChange = summary?.income_change_percentage || 0;
    const expenseChange = summary?.expense_change_percentage || 0;

    const getStatusColor = (status) => {
        switch(status) {
            case 'surplus': return 'text-green-600';
            case 'deficit': return 'text-red-600';
            default: return 'text-gray-600';
        }
    };

    const getStatusBg = (status) => {
        switch(status) {
            case 'surplus': return 'bg-green-50';
            case 'deficit': return 'bg-red-50';
            default: return 'bg-gray-50';
        }
    };

    // Helper function to safely format numbers
    const formatNumber = (value) => {
        const num = parseFloat(value) || 0;
        return num.toFixed(1);
    };

    const formatCurrency = (value) => {
        const num = parseFloat(value) || 0;
        return new Intl.NumberFormat('en-US', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }).format(num);
    };

    return (
        <div className="space-y-6">
            {/* Main Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <IncomeStatCard
                    title="Total Income"
                    value={currentMonth.total_income || 0}
                    currency={currency}
                    change={incomeChange}
                    trend={incomeChange > 0 ? 'up' : incomeChange < 0 ? 'down' : 'neutral'}
                    icon={<TrendingUp />}
                    subtitle={currentMonth.period_display}
                    loading={loading}
                />

                <IncomeStatCard
                    title="Total Expenses"
                    value={currentMonth.total_expenses || 0}
                    currency={currency}
                    change={expenseChange}
                    trend={expenseChange > 0 ? 'down' : expenseChange < 0 ? 'up' : 'neutral'}
                    icon={<TrendingDown />}
                    subtitle={currentMonth.period_display}
                    loading={loading}
                />

                <IncomeStatCard
                    title="Net Cash Flow"
                    value={currentMonth.net_cashflow || 0}
                    currency={currency}
                    trend={currentMonth.net_cashflow > 0 ? 'up' : currentMonth.net_cashflow < 0 ? 'down' : 'neutral'}
                    icon={<DollarSign />}
                    subtitle={`${currentMonth.is_surplus ? 'Surplus' : currentMonth.is_deficit ? 'Deficit' : 'Balanced'}`}
                    loading={loading}
                />

                <IncomeStatCard
                    title="Savings Rate"
                    value={`${formatNumber(currentMonth.savings_rate)}%`}
                    trend={parseFloat(currentMonth.savings_rate) > 20 ? 'up' : parseFloat(currentMonth.savings_rate) < 10 ? 'down' : 'neutral'}
                    icon={<RefreshCw />}
                    subtitle="Of total income"
                    loading={loading}
                />
            </div>

            {/* Additional Info Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {/* Recurring Income */}
                <div className="bg-gradient-to-br from-blue-50 to-blue-100 rounded-xl p-5 border border-blue-200">
                    <div className="flex items-start justify-between mb-3">
                        <div className="p-2 bg-blue-500 rounded-lg">
                            <RefreshCw className="text-white" size={20} />
                        </div>
                        <span className="text-xs font-semibold text-blue-700 bg-blue-200 px-2 py-1 rounded-full">
                            Monthly
                        </span>
                    </div>
                    <p className="text-sm font-medium text-blue-900 mb-1">Recurring Income</p>
                    <p className="text-2xl font-bold text-blue-900">
                        {currency} {formatCurrency(summary?.monthly_recurring_income)}
                    </p>
                    <p className="text-xs text-blue-700 mt-2">Reliable monthly earnings</p>
                </div>

                {/* Income Sources */}
                <div className="bg-gradient-to-br from-purple-50 to-purple-100 rounded-xl p-5 border border-purple-200">
                    <div className="flex items-start justify-between mb-3">
                        <div className="p-2 bg-purple-500 rounded-lg">
                            <Calendar className="text-white" size={20} />
                        </div>
                        <span className="text-xs font-semibold text-purple-700 bg-purple-200 px-2 py-1 rounded-full">
                            Active
                        </span>
                    </div>
                    <p className="text-sm font-medium text-purple-900 mb-1">Income Sources</p>
                    <p className="text-2xl font-bold text-purple-900">
                        {summary?.income_sources_count || 0}
                    </p>
                    <p className="text-xs text-purple-700 mt-2">Different income categories</p>
                </div>

                {/* Status Card */}
                <div className={`bg-gradient-to-br ${
                    currentMonth.is_surplus 
                        ? 'from-green-50 to-green-100 border-green-200' 
                        : currentMonth.is_deficit 
                        ? 'from-red-50 to-red-100 border-red-200'
                        : 'from-gray-50 to-gray-100 border-gray-200'
                } rounded-xl p-5 border`}>
                    <div className="flex items-start justify-between mb-3">
                        <div className={`p-2 ${
                            currentMonth.is_surplus ? 'bg-green-500' : currentMonth.is_deficit ? 'bg-red-500' : 'bg-gray-500'
                        } rounded-lg`}>
                            {currentMonth.is_surplus ? (
                                <TrendingUp className="text-white" size={20} />
                            ) : currentMonth.is_deficit ? (
                                <TrendingDown className="text-white" size={20} />
                            ) : (
                                <DollarSign className="text-white" size={20} />
                            )}
                        </div>
                        <span className={`text-xs font-semibold ${
                            currentMonth.is_surplus ? 'text-green-700 bg-green-200' : 
                            currentMonth.is_deficit ? 'text-red-700 bg-red-200' : 
                            'text-gray-700 bg-gray-200'
                        } px-2 py-1 rounded-full`}>
                            {currentMonth.period_display || 'Current Month'}
                        </span>
                    </div>
                    <p className={`text-sm font-medium ${getStatusColor(
                        currentMonth.is_surplus ? 'surplus' : currentMonth.is_deficit ? 'deficit' : 'balanced'
                    )} mb-1`}>
                        Financial Status
                    </p>
                    <p className={`text-2xl font-bold ${getStatusColor(
                        currentMonth.is_surplus ? 'surplus' : currentMonth.is_deficit ? 'deficit' : 'balanced'
                    )}`}>
                        {currentMonth.is_surplus ? 'Surplus' : currentMonth.is_deficit ? 'Deficit' : 'Balanced'}
                    </p>
                    <p className={`text-xs ${getStatusColor(
                        currentMonth.is_surplus ? 'surplus' : currentMonth.is_deficit ? 'deficit' : 'balanced'
                    )} mt-2`}>
                        {currentMonth.is_surplus 
                            ? 'You\'re earning more than spending' 
                            : currentMonth.is_deficit 
                            ? 'Expenses exceed income'
                            : 'Income equals expenses'}
                    </p>
                </div>
            </div>

            {/* Top Income Sources */}
            {summary?.top_income_sources && summary.top_income_sources.length > 0 && (
                <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                    <h3 className="text-lg font-bold text-gray-900 mb-4">Top Income Sources</h3>
                    <div className="space-y-3">
                        {summary.top_income_sources.map((source, index) => {
                            const total = parseFloat(source.total || 0);
                            const maxAmount = parseFloat(summary.top_income_sources[0].total || 1);
                            const percentage = (total / maxAmount) * 100;

                            return (
                                <div key={index} className="space-y-2">
                                    <div className="flex items-center justify-between text-sm">
                                        <span className="font-medium text-gray-900">{source.category}</span>
                                        <span className="font-bold text-gray-900">
                                            {currency} {formatCurrency(total)}
                                        </span>
                                    </div>
                                    <div className="w-full bg-gray-200 rounded-full h-2 overflow-hidden">
                                        <div
                                            className="bg-gradient-to-r from-blue-500 to-blue-600 h-full rounded-full transition-all duration-500"
                                            style={{ width: `${percentage}%` }}
                                        />
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}
        </div>
    );
};

export default IncomeSummary;

import React, { useState, useEffect } from 'react';
import { Plus, Filter, Download, RefreshCw, TrendingUp } from 'lucide-react';
import { useIncome } from '../../../contexts/IncomeContext';
import IncomeSummary from './IncomeSummary';
import IncomeList from './IncomeList';
import IncomeForm from './IncomeForm';
import QuickIncomeModal from './QuickIncomeModal';
import IncomeVsExpenseChart from './IncomeVsExpenseChart';
import MonthlyTrendsChart from './MonthlyTrendsChart';
import CategoryPieChart from './CategoryPieChart';

const IncomeDashboard = () => {
    const {
        incomes,
        summary,
        history,
        incomeVsExpense,
        loading,
        error,
        fetchIncomes,
        fetchSummary,
        fetchHistory,
        fetchIncomeVsExpense,
        deleteIncome
    } = useIncome();

    const [showIncomeForm, setShowIncomeForm] = useState(false);
    const [showQuickIncome, setShowQuickIncome] = useState(false);
    const [selectedIncome, setSelectedIncome] = useState(null);
    const [filters, setFilters] = useState({
        status: '',
        recurring: '',
        category: '',
        start_date: '',
        end_date: '',
        current_month: 'true'
    });
    const [activeTab, setActiveTab] = useState('overview');

    // Initial data fetch
    useEffect(() => {
        fetchIncomes(filters);
        fetchHistory(6);
        fetchIncomeVsExpense();
    }, []);

    // Refetch incomes when filters change
    useEffect(() => {
        fetchIncomes(filters);
    }, [filters]);

    const handleFilterChange = (key, value) => {
        setFilters(prev => ({
            ...prev,
            [key]: value,
            // Reset current_month when date filters are applied
            ...(key === 'start_date' || key === 'end_date' ? { current_month: 'false' } : {})
        }));
    };

    const handleClearFilters = () => {
        setFilters({
            status: '',
            recurring: '',
            category: '',
            start_date: '',
            end_date: '',
            current_month: 'true'
        });
    };

    const handleEditIncome = (income) => {
        setSelectedIncome(income);
        setShowIncomeForm(true);
    };

    const handleCloseForm = () => {
        setSelectedIncome(null);
        setShowIncomeForm(false);
    };

    const handleFormSuccess = () => {
        fetchIncomes(filters);
        fetchSummary();
    };

    const handleRefresh = async () => {
        await Promise.all([
            fetchIncomes(filters),
            fetchSummary(),
            fetchHistory(6),
            fetchIncomeVsExpense()
        ]);
    };

    const hasActiveFilters = Object.entries(filters).some(
        ([key, value]) => key !== 'current_month' && value !== ''
    );

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Header */}
            <div className="bg-white border-b border-gray-200 sticky top-0 z-10">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
                    <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
                        <div className="min-w-0">
                            <h1 className="flex items-center gap-3 text-2xl font-bold text-gray-900 sm:text-3xl">
                                <span className="inline-flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-green-400 to-green-600 text-white sm:h-12 sm:w-12">
                                    <TrendingUp size={24} />
                                </span>
                                Income Manager
                            </h1>
                            <p className="text-sm text-gray-500 mt-1">Track and manage all your income sources</p>
                        </div>

                        <div className="grid grid-cols-1 gap-2 sm:grid-cols-3 sm:gap-3">
                            <button
                                onClick={handleRefresh}
                                disabled={loading}
                                className="inline-flex items-center justify-center gap-2 rounded-lg border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 transition-colors duration-200 hover:bg-gray-50 disabled:opacity-50"
                            >
                                <RefreshCw size={16} className={loading ? 'animate-spin' : ''} />
                                Refresh
                            </button>
                            
                            <button
                                onClick={() => setShowQuickIncome(true)}
                                className="inline-flex items-center justify-center gap-2 rounded-lg bg-green-600 px-4 py-2 text-sm font-medium text-white shadow-lg transition-colors duration-200 hover:bg-green-700 hover:shadow-xl"
                            >
                                <Plus size={16} />
                                Quick Add
                            </button>
                            
                            <button
                                onClick={() => {
                                    setSelectedIncome(null);
                                    setShowIncomeForm(true);
                                }}
                                className="inline-flex items-center justify-center gap-2 rounded-lg bg-amber-400 px-4 py-2 text-sm font-medium text-slate-950 shadow-lg shadow-amber-300/40 transition-colors duration-200 hover:bg-amber-300 hover:shadow-xl"
                            >
                                <Plus size={16} />
                                Add Income
                            </button>
                        </div>
                    </div>

                    {/* Tabs */}
                    <div className="mt-6 overflow-x-auto border-b border-gray-200">
                        <div className="flex min-w-max items-center gap-2">
                        <button
                            onClick={() => setActiveTab('overview')}
                            className={`px-4 py-2 font-medium text-sm transition-colors duration-200 border-b-2 ${
                                activeTab === 'overview'
                                    ? 'border-blue-600 text-blue-600'
                                    : 'border-transparent text-gray-500 hover:text-gray-700'
                            }`}
                        >
                            Overview
                        </button>
                        <button
                            onClick={() => setActiveTab('transactions')}
                            className={`px-4 py-2 font-medium text-sm transition-colors duration-200 border-b-2 ${
                                activeTab === 'transactions'
                                    ? 'border-blue-600 text-blue-600'
                                    : 'border-transparent text-gray-500 hover:text-gray-700'
                            }`}
                        >
                            All Income
                        </button>
                        <button
                            onClick={() => setActiveTab('analytics')}
                            className={`px-4 py-2 font-medium text-sm transition-colors duration-200 border-b-2 ${
                                activeTab === 'analytics'
                                    ? 'border-blue-600 text-blue-600'
                                    : 'border-transparent text-gray-500 hover:text-gray-700'
                            }`}
                        >
                            Analytics
                        </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Error Alert */}
            {error && (
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-6">
                    <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-start gap-3">
                        <svg className="w-5 h-5 mt-0.5 shrink-0" fill="currentColor" viewBox="0 0 20 20">
                            <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                        </svg>
                        <span>{error}</span>
                    </div>
                </div>
            )}

            {/* Main Content */}
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {/* Overview Tab */}
                {activeTab === 'overview' && (
                    <div className="space-y-6">
                        <IncomeSummary summary={summary} loading={loading} />
                        
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                            <IncomeVsExpenseChart data={incomeVsExpense} loading={loading} />
                            <MonthlyTrendsChart history={history} loading={loading} />
                        </div>

                        {/* Recent Income */}
                        {summary?.recent_incomes && summary.recent_incomes.length > 0 && (
                            <div>
                                <div className="flex items-center justify-between mb-4">
                                    <h2 className="text-xl font-bold text-gray-900">Recent Income</h2>
                                    <button
                                        onClick={() => setActiveTab('transactions')}
                                        className="text-sm font-medium text-blue-600 hover:text-blue-700"
                                    >
                                        View All
                                    </button>
                                </div>
                                <IncomeList
                                    incomes={summary.recent_incomes.slice(0, 5)}
                                    onEdit={handleEditIncome}
                                    onDelete={deleteIncome}
                                    currency={summary.currency}
                                />
                            </div>
                        )}
                    </div>
                )}

                {/* Transactions Tab */}
                {activeTab === 'transactions' && (
                    <div className="space-y-6">
                        {/* Filters */}
                        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                            <div className="flex items-center justify-between mb-4">
                                <h3 className="text-lg font-semibold text-gray-900 flex items-center gap-2">
                                    <Filter size={20} />
                                    Filters
                                </h3>
                                {hasActiveFilters && (
                                    <button
                                        onClick={handleClearFilters}
                                        className="text-sm font-medium text-blue-600 hover:text-blue-700"
                                    >
                                        Clear All
                                    </button>
                                )}
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                                {/* Status Filter */}
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-2">
                                        Status
                                    </label>
                                    <select
                                        value={filters.status}
                                        onChange={(e) => handleFilterChange('status', e.target.value)}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                                    >
                                        <option value="">All Status</option>
                                        <option value="RECEIVED">Received</option>
                                        <option value="PENDING">Pending</option>
                                        <option value="EXPECTED">Expected</option>
                                    </select>
                                </div>

                                {/* Recurring Filter */}
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-2">
                                        Type
                                    </label>
                                    <select
                                        value={filters.recurring}
                                        onChange={(e) => handleFilterChange('recurring', e.target.value)}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                                    >
                                        <option value="">All Types</option>
                                        <option value="true">Recurring Only</option>
                                        <option value="false">One-time Only</option>
                                    </select>
                                </div>

                                {/* Start Date */}
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-2">
                                        From Date
                                    </label>
                                    <input
                                        type="date"
                                        value={filters.start_date}
                                        onChange={(e) => handleFilterChange('start_date', e.target.value)}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                                    />
                                </div>

                                {/* End Date */}
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-2">
                                        To Date
                                    </label>
                                    <input
                                        type="date"
                                        value={filters.end_date}
                                        onChange={(e) => handleFilterChange('end_date', e.target.value)}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                                    />
                                </div>
                            </div>

                            {/* Active Filters Display */}
                            {hasActiveFilters && (
                                <div className="mt-4 flex flex-wrap gap-2">
                                    {Object.entries(filters).map(([key, value]) => {
                                        if (key === 'current_month' || !value) return null;
                                        return (
                                            <span
                                                key={key}
                                                className="inline-flex items-center gap-2 px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-sm font-medium"
                                            >
                                                {key.replace('_', ' ')}: {value}
                                                <button
                                                    onClick={() => handleFilterChange(key, '')}
                                                    className="hover:text-blue-900"
                                                >
                                                    x
                                                </button>
                                            </span>
                                        );
                                    })}
                                </div>
                            )}
                        </div>

                        {/* Income List */}
                        <div>
                            <div className="flex items-center justify-between mb-4">
                                <h2 className="text-xl font-bold text-gray-900">
                                    Income Transactions
                                    {incomes.length > 0 && (
                                        <span className="ml-2 text-sm font-normal text-gray-500">
                                            ({incomes.length} {incomes.length === 1 ? 'entry' : 'entries'})
                                        </span>
                                    )}
                                </h2>
                                <button
                                    disabled={incomes.length === 0}
                                    className="inline-flex items-center gap-2 px-4 py-2 border border-gray-300 text-gray-700 bg-white rounded-lg font-medium hover:bg-gray-50 transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    <Download size={16} />
                                    Export
                                </button>
                            </div>
                            
                            <IncomeList
                                incomes={incomes}
                                onEdit={handleEditIncome}
                                onDelete={deleteIncome}
                                loading={loading}
                                currency={summary?.currency || 'KES'}
                            />
                        </div>
                    </div>
                )}

                {/* Analytics Tab */}
                {activeTab === 'analytics' && (
                    <div className="space-y-6">
                        {/* Top Section - Trends and Comparison */}
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                            <MonthlyTrendsChart history={history} loading={loading} />
                            <IncomeVsExpenseChart data={incomeVsExpense} loading={loading} />
                        </div>

                        {/* Pie Charts - Only here! */}
                        {incomeVsExpense && (
                            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                                {incomeVsExpense.income_breakdown && incomeVsExpense.income_breakdown.length > 0 && (
                                    <CategoryPieChart
                                        data={incomeVsExpense.income_breakdown}
                                        title="Income by Category"
                                        type="income"
                                    />
                                )}

                                {incomeVsExpense.expense_breakdown && incomeVsExpense.expense_breakdown.length > 0 && (
                                    <CategoryPieChart
                                        data={incomeVsExpense.expense_breakdown}
                                        title="Expenses by Category"
                                        type="expense"
                                    />
                                )}
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* Modals */}
            {showQuickIncome && (
                <QuickIncomeModal
                    isOpen={showQuickIncome}
                    onClose={() => setShowQuickIncome(false)}
                />
            )}

            {showIncomeForm && (
                <IncomeForm
                    income={selectedIncome}
                    onClose={handleCloseForm}
                    onSuccess={handleFormSuccess}
                />
            )}
        </div>
    );
};

export default IncomeDashboard;

import React from 'react';

const formatCurrency = (value, currency = 'KES') => new Intl.NumberFormat('en-KE', {
    style: 'currency',
    currency,
    maximumFractionDigits: 0,
}).format(value || 0);

const TableHeader = ({ title, column1, column2 }) => (
    <div className="grid grid-cols-[1fr_80px_100px] bg-slate-700 p-3 text-[10px] font-bold uppercase tracking-wider text-white shadow-sm">
        <div>{column1}</div>
        <div className="text-center">Source</div>
        <div className="text-right">{column2}</div>
    </div>
);

const TableRow = ({ label, value, currency, source }) => (
    <div className="grid grid-cols-[1fr_80px_100px] items-center border-b border-slate-100 p-3 text-sm text-slate-700 last:border-0 hover:bg-slate-50/50">
        <div className="truncate pr-4 font-medium">{label}</div>
        <div className="text-center">
            <span className={`rounded-full px-2 py-0.5 text-[10px] font-bold uppercase ${
                source === 'Goal' ? 'bg-emerald-100 text-emerald-700' :
                source === 'Debt' ? 'bg-rose-100 text-rose-700' :
                'bg-slate-100 text-slate-600'
            }`}>
                {source}
            </span>
        </div>
        <div className="text-right font-bold text-slate-900">{formatCurrency(value, currency)}</div>
    </div>
);

const NetWorthBreakdownCard = ({ breakdown }) => {
    const currency = breakdown?.currency || 'KES';

    const assets = [
        ...(breakdown?.assets?.manual || []).map(a => ({ ...a, source: 'Manual' })),
        ...(breakdown?.assets?.fromGoals || []).map(a => ({ ...a, source: 'Goal' })),
    ];

    const liabilities = [
        ...(breakdown?.liabilities?.debts || []).map(l => ({ ...l, source: 'Debt' })),
        ...(breakdown?.liabilities?.other || []).map(l => ({ ...l, source: 'Manual' })),
    ];

    const totalAssets = assets.reduce((sum, item) => sum + (item.value || 0), 0);
    const totalLiabilities = liabilities.reduce((sum, item) => sum + (item.value || 0), 0);

    return (
        <div className="grid gap-8 lg:grid-cols-2">
            {/* Assets Table */}
            <div className="flex flex-col">
                <div className="mb-4 flex items-center justify-between">
                    <h3 className="text-xl font-bold text-slate-800">Assets</h3>
                </div>
                <div className="overflow-hidden rounded-lg border border-slate-200 bg-white shadow-sm">
                    <TableHeader column1="Asset Name" column2="Value" />
                    <div className="min-h-[160px]">
                        {assets.length > 0 ? (
                            assets.map((item) => (
                                <TableRow 
                                    key={item.id} 
                                    label={item.label} 
                                    value={item.value} 
                                    currency={currency} 
                                    source={item.source}
                                />
                            ))
                        ) : (
                            <div className="flex flex-col items-center justify-center p-12 text-center text-sm text-slate-400">
                                <p className="italic">No assets found</p>
                                <p className="mt-1 text-[10px] uppercase tracking-widest text-slate-300 font-bold">Auto-syncs from Goals & Savings</p>
                            </div>
                        )}
                    </div>
                    <div className="grid grid-cols-[1fr_100px] items-center bg-slate-50 p-4 text-sm font-bold text-slate-900">
                        <div className="uppercase tracking-widest text-[10px] text-slate-500">Total Assets</div>
                        <div className="text-right text-base">{formatCurrency(totalAssets, currency)}</div>
                    </div>
                </div>
            </div>

            {/* Liabilities Table */}
            <div className="flex flex-col">
                <div className="mb-4 flex items-center justify-between">
                    <h3 className="text-xl font-bold text-slate-800">Liabilities</h3>
                </div>
                <div className="overflow-hidden rounded-lg border border-slate-200 bg-white shadow-sm">
                    <TableHeader column1="Liability Name" column2="Owed" />
                    <div className="min-h-[160px]">
                        {liabilities.length > 0 ? (
                            liabilities.map((item) => (
                                <TableRow 
                                    key={item.id} 
                                    label={item.label} 
                                    value={item.value} 
                                    currency={currency} 
                                    source={item.source}
                                />
                            ))
                        ) : (
                            <div className="flex flex-col items-center justify-center p-12 text-center text-sm text-slate-400">
                                <p className="italic">No liabilities found</p>
                                <p className="mt-1 text-[10px] uppercase tracking-widest text-slate-300 font-bold">Auto-syncs from Debt Module</p>
                            </div>
                        )}
                    </div>
                    <div className="grid grid-cols-[1fr_100px] items-center bg-slate-50 p-4 text-sm font-bold text-slate-900">
                        <div className="uppercase tracking-widest text-[10px] text-slate-500">Total Liabilities</div>
                        <div className="text-right text-base">{formatCurrency(totalLiabilities, currency)}</div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default NetWorthBreakdownCard;

import React, { useEffect, useState } from 'react';
import Button from '../../Button';

const assetEmptyForm = {
    name: '',
    categoryId: '',
    currentValue: '',
    purchaseValue: '',
    currency: 'KES',
    purchaseDate: '',
    interestRate: '',
    institution: '',
    accountNumber: '',
    isLiquid: false,
    includeInNetWorth: true,
    lastValuedDate: '',
    notes: '',
};

const liabilityEmptyForm = {
    name: '',
    categoryId: '',
    amount: '',
    currency: 'KES',
    dueDate: '',
    creditor: '',
    status: 'ACTIVE',
    includeInNetWorth: true,
    notes: '',
};

const currencyOptions = ['KES', 'USD', 'EUR', 'GBP', 'TZS', 'UGX'];

const NetWorthForm = ({
    kind,
    categories,
    initialValues,
    onSubmit,
    onCancel,
    isSubmitting,
    variant = 'card',
    showCategoryIdNotice = false,
}) => {
    const [formValues, setFormValues] = useState(kind === 'asset' ? assetEmptyForm : liabilityEmptyForm);
    const isModal = variant === 'modal';
    const inputClasses = isModal
        ? 'rounded-xl border border-gray-200 px-3 py-2.5 text-sm text-gray-900 outline-none transition-colors focus:border-primary-500'
        : 'rounded-2xl border border-gray-200 px-4 py-3 text-base text-gray-900 outline-none transition-colors focus:border-primary-500';
    const textareaClasses = isModal
        ? 'rounded-xl border border-gray-200 px-3 py-2.5 text-sm text-gray-900 outline-none transition-colors focus:border-primary-500'
        : 'rounded-2xl border border-gray-200 px-4 py-3 text-base text-gray-900 outline-none transition-colors focus:border-primary-500';

    useEffect(() => {
        const defaultCategoryId = categories?.[0]?.categoryId ? String(categories[0].categoryId) : '';

        if (kind === 'asset') {
            if (initialValues) {
                setFormValues({
                    name: initialValues.name ?? '',
                    categoryId: initialValues.category ? String(initialValues.category) : defaultCategoryId,
                    currentValue: initialValues.currentValue ?? '',
                    purchaseValue: initialValues.purchaseValue ?? '',
                    currency: initialValues.currency ?? 'KES',
                    purchaseDate: initialValues.purchaseDate ?? '',
                    interestRate: initialValues.interestRate ?? '',
                    institution: initialValues.institution ?? '',
                    accountNumber: initialValues.accountNumber ?? '',
                    isLiquid: initialValues.isLiquid ?? false,
                    includeInNetWorth: initialValues.includeInNetWorth ?? true,
                    lastValuedDate: initialValues.lastValuedDate ?? '',
                    notes: initialValues.notes ?? '',
                });
                return;
            }

            setFormValues({
                ...assetEmptyForm,
                categoryId: defaultCategoryId,
            });
            return;
        }

        if (initialValues) {
            setFormValues({
                name: initialValues.name ?? '',
                categoryId: initialValues.category ? String(initialValues.category) : defaultCategoryId,
                amount: initialValues.amount ?? '',
                currency: initialValues.currency ?? 'KES',
                dueDate: initialValues.dueDate ?? '',
                creditor: initialValues.creditor ?? '',
                status: initialValues.status ?? 'ACTIVE',
                includeInNetWorth: initialValues.includeInNetWorth ?? true,
                notes: initialValues.notes ?? '',
            });
            return;
        }

        setFormValues({
            ...liabilityEmptyForm,
            categoryId: defaultCategoryId,
        });
    }, [categories, initialValues, kind]);

    const handleChange = (event) => {
        const { name, value, type, checked } = event.target;
        setFormValues((current) => ({
            ...current,
            [name]: type === 'checkbox' ? checked : value,
        }));
    };

    const handleSubmit = (event) => {
        event.preventDefault();
        onSubmit(formValues);
    };

    const label = kind === 'asset' ? 'asset' : 'liability';

    return (
        <form onSubmit={handleSubmit} className={isModal ? 'space-y-4' : 'rounded-3xl border border-gray-100 bg-white p-6 shadow-sm'}>
            <div>
                <p className="text-sm font-semibold uppercase tracking-[0.24em] text-primary-700">{label} details</p>
                <p className="mt-1 text-xs leading-5 text-gray-600">
                    {kind === 'asset'
                        ? 'Use this form to create or update assets against the live API.'
                        : 'Use this form to create or update liabilities against the live API.'}
                </p>
            </div>

            {showCategoryIdNotice && (
                <div className="rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900">
                    The live API currently expects numeric category IDs on create and update, while the category list endpoint only exposes names and UUIDs.
                    This form pre-fills the category ID using the returned list order so endpoint testing can still move forward.
                </div>
            )}

            <div className={`grid ${isModal ? 'gap-3 md:grid-cols-2' : 'gap-4 md:grid-cols-2'}`}>
                <Field
                    label={kind === 'asset' ? 'Asset name' : 'Liability name'}
                    name="name"
                    value={formValues.name}
                    onChange={handleChange}
                    placeholder={kind === 'asset' ? 'Emergency fund' : 'Rent arrears'}
                    required
                    className={inputClasses}
                />

                <label className="flex flex-col gap-2 text-sm font-medium text-gray-700">
                    Suggested category
                    <select
                        value={formValues.categoryId}
                        onChange={(event) => {
                            const { value } = event.target;
                            setFormValues((current) => ({
                                ...current,
                                categoryId: value,
                            }));
                        }}
                        className={inputClasses}
                    >
                        {!categories?.length && <option value="">No categories loaded</option>}
                        {categories?.map((category) => (
                            <option key={category.id} value={String(category.categoryId)}>
                                {category.name} (ID {category.categoryId})
                            </option>
                        ))}
                    </select>
                </label>

                <Field
                    label="Category ID"
                    name="categoryId"
                    type="number"
                    min="1"
                    step="1"
                    value={formValues.categoryId}
                    onChange={handleChange}
                    required
                    className={inputClasses}
                />

                <label className="flex flex-col gap-2 text-sm font-medium text-gray-700">
                    Currency
                    <select
                        name="currency"
                        value={formValues.currency}
                        onChange={handleChange}
                        className={inputClasses}
                    >
                        {currencyOptions.map((currency) => (
                            <option key={currency} value={currency}>
                                {currency}
                            </option>
                        ))}
                    </select>
                </label>

                {kind === 'asset' ? (
                    <>
                        <Field
                            label="Current value"
                            name="currentValue"
                            type="number"
                            min="0"
                            step="0.01"
                            value={formValues.currentValue}
                            onChange={handleChange}
                            required
                            className={inputClasses}
                        />
                        <Field
                            label="Purchase value"
                            name="purchaseValue"
                            type="number"
                            min="0"
                            step="0.01"
                            value={formValues.purchaseValue}
                            onChange={handleChange}
                            className={inputClasses}
                        />
                        <Field
                            label="Institution or location"
                            name="institution"
                            value={formValues.institution}
                            onChange={handleChange}
                            placeholder="KCB Bank"
                            className={inputClasses}
                        />
                        <Field
                            label="Account or reference number"
                            name="accountNumber"
                            value={formValues.accountNumber}
                            onChange={handleChange}
                            placeholder="Optional"
                            className={inputClasses}
                        />
                        <Field label="Purchase date" name="purchaseDate" type="date" value={formValues.purchaseDate} onChange={handleChange} className={inputClasses} />
                        <Field label="Last valued date" name="lastValuedDate" type="date" value={formValues.lastValuedDate} onChange={handleChange} className={inputClasses} />
                        <Field
                            label="Interest or growth rate (%)"
                            name="interestRate"
                            type="number"
                            min="0"
                            step="0.01"
                            value={formValues.interestRate}
                            onChange={handleChange}
                            className={inputClasses}
                        />

                        <div className="space-y-3 rounded-2xl border border-slate-200 bg-slate-50/70 px-4 py-4 md:col-span-2">
                            <label className="flex items-center gap-3 text-sm font-medium text-gray-700">
                                <input
                                    type="checkbox"
                                    name="isLiquid"
                                    checked={formValues.isLiquid}
                                    onChange={handleChange}
                                    className="h-5 w-5 rounded border-gray-300 text-primary-600 focus:ring-primary-500"
                                />
                                Mark as a liquid asset
                            </label>
                            <label className="flex items-center gap-3 text-sm font-medium text-gray-700">
                                <input
                                    type="checkbox"
                                    name="includeInNetWorth"
                                    checked={formValues.includeInNetWorth}
                                    onChange={handleChange}
                                    className="h-5 w-5 rounded border-gray-300 text-primary-600 focus:ring-primary-500"
                                />
                                Include in net worth calculations
                            </label>
                        </div>
                    </>
                ) : (
                    <>
                        <Field
                            label="Amount owed"
                            name="amount"
                            type="number"
                            min="0"
                            step="0.01"
                            value={formValues.amount}
                            onChange={handleChange}
                            required
                            className={inputClasses}
                        />
                        <Field
                            label="Creditor"
                            name="creditor"
                            value={formValues.creditor}
                            onChange={handleChange}
                            placeholder="Landlord or provider"
                            className={inputClasses}
                        />
                        <Field label="Due date" name="dueDate" type="date" value={formValues.dueDate} onChange={handleChange} className={inputClasses} />

                        <label className="flex flex-col gap-2 text-sm font-medium text-gray-700">
                            Status
                            <select
                                name="status"
                                value={formValues.status}
                                onChange={handleChange}
                                className={inputClasses}
                            >
                                <option value="ACTIVE">Active</option>
                                <option value="PAID">Paid</option>
                                <option value="DISPUTED">Disputed</option>
                            </select>
                        </label>

                        <div className="rounded-2xl border border-slate-200 bg-slate-50/70 px-4 py-4 md:col-span-2">
                            <label className="flex items-center gap-3 text-sm font-medium text-gray-700">
                                <input
                                    type="checkbox"
                                    name="includeInNetWorth"
                                    checked={formValues.includeInNetWorth}
                                    onChange={handleChange}
                                    className="h-5 w-5 rounded border-gray-300 text-primary-600 focus:ring-primary-500"
                                />
                                Include in net worth calculations
                            </label>
                        </div>
                    </>
                )}

                <label className="flex flex-col gap-2 text-sm font-medium text-gray-700 md:col-span-2">
                    Notes
                    <textarea
                        name="notes"
                        value={formValues.notes}
                        onChange={handleChange}
                        rows={isModal ? 3 : 4}
                        placeholder="Anything helpful for tracking or testing the endpoint."
                        className={textareaClasses}
                    />
                </label>
            </div>

            <div className="mt-5 flex flex-col gap-2.5 sm:flex-row sm:justify-end">
                <Button type="button" variant="outline" size="sm" className="justify-center" onClick={onCancel}>
                    Cancel
                </Button>
                <Button type="submit" variant="primary" size="sm" className="justify-center" disabled={isSubmitting}>
                    {isSubmitting
                        ? `Saving ${label}...`
                        : initialValues
                            ? 'Save changes'
                            : `Add ${label}`}
                </Button>
            </div>
        </form>
    );
};

